package com.teleportpretile;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Reads the tiles marked with RuneLite's Tile Markers (ground markers) plugin, for any region, straight from the
 * config where that plugin saves them. Works for regions that aren't loaded, which is the point: the destination
 * of a teleport isn't loaded until the player gets there.
 *
 * <p>Read only, always: nothing in this plugin writes to the Tile Markers config. Colour overrides and the blur
 * change only how this plugin draws its preview of the markers.
 */
@Slf4j
@Singleton
class GroundMarkerReader
{
	static final String GROUP = "groundMarker";
	private static final String REGION_PREFIX = "region_";

	/** A marked tile in world coordinates. */
	@Value
	static class Marker
	{
		int x;
		int y;
		int plane;
		/** Null for old markers saved without a colour: the Tile Markers default colour applies. */
		@Nullable
		Color color;
		@Nullable
		String label;
	}

	/** The fields the Tile Markers plugin saves for each tile (its GroundMarkerPoint). */
	private static final class SavedPoint
	{
		int regionId;
		int regionX;
		int regionY;
		int z;
		Color color;
		String label;
	}

	private final ConfigManager configManager;
	private final Gson gson;
	private final Map<Integer, List<Marker>> cache = new HashMap<>();

	@Inject
	GroundMarkerReader(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Forget what was read, after the Tile Markers config changes. */
	synchronized void invalidate()
	{
		cache.clear();
	}

	/** Every marker on {@code plane} within {@code range} tiles (Chebyshev) of tile (x, y). */
	synchronized List<Marker> around(int x, int y, int plane, int range)
	{
		List<Marker> out = new ArrayList<>();
		for (int rx = (x - range) >> 6; rx <= (x + range) >> 6; rx++)
		{
			for (int ry = (y - range) >> 6; ry <= (y + range) >> 6; ry++)
			{
				for (Marker m : region((rx << 8) | ry))
				{
					if (m.plane == plane && Math.abs(m.x - x) <= range && Math.abs(m.y - y) <= range)
					{
						out.add(m);
					}
				}
			}
		}
		return out;
	}

	private List<Marker> region(int regionId)
	{
		return cache.computeIfAbsent(regionId, this::load);
	}

	private List<Marker> load(int regionId)
	{
		String json = configManager.getConfiguration(GROUP, REGION_PREFIX + regionId);
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}
		List<SavedPoint> points;
		try
		{
			points = gson.fromJson(json, new TypeToken<List<SavedPoint>>()
			{
			}.getType());
		}
		catch (JsonParseException e)
		{
			log.debug("unreadable tile markers for region {}", regionId, e);
			return Collections.emptyList();
		}
		if (points == null)
		{
			return Collections.emptyList();
		}
		List<Marker> out = new ArrayList<>(points.size());
		for (SavedPoint p : points)
		{
			if (p == null)
			{
				continue;
			}
			int id = p.regionId != 0 ? p.regionId : regionId;
			int worldX = ((id >>> 8) << 6) + p.regionX;
			int worldY = ((id & 0xFF) << 6) + p.regionY;
			out.add(new Marker(worldX, worldY, p.z, p.color, p.label));
		}
		return out;
	}
}

package com.teleportpretile;

import com.teleportpretile.render.OverrideWhen;
import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * The plugin's settings. Descriptions are the panel's tooltips, which don't wrap on their own; RuneLite shows them as
 * HTML, so they carry a line break every 50 or so characters.
 */
@ConfigGroup(TeleportPreTileConfig.GROUP)
public interface TeleportPreTileConfig extends Config
{
	String GROUP = "teleportpretile";
	/** Config key prefix for the learned meaning of "last destination" varbit values (see LastDestination). */
	String LAST_DESTINATION_PREFIX = "lastDestination.";
	/** The Forget learned data checkbox: ticking it asks, then forgets, then unticks itself. */
	String FORGET_LEARNED = "forgetLearned";

	@ConfigItem(
		keyName = "showOnClick",
		name = "Show on click",
		description = "Show the destination's tile markers as soon as you<br>"
			+ "click the teleport. When off, they show once the<br>teleport animation starts.",
		position = 1
	)
	default boolean showOnClick()
	{
		return true;
	}

	@ConfigItem(
		keyName = "drawDistance",
		name = "Draw distance",
		description = "Show tile markers up to this many tiles from<br>where you will land.",
		position = 2
	)
	@Range(min = 1, max = 100)
	default int drawDistance()
	{
		return 32;
	}

	@ConfigItem(
		keyName = "snapToTrueTile",
		name = "Snap to true tile",
		description = "Place the markers from the tile you are really on<br>"
			+ "(your true tile), so they jump a tile at a time<br>"
			+ "while you move. When off, they follow your<br>character smoothly.",
		position = 3
	)
	default boolean snapToTrueTile()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showOnMinimap",
		name = "Show on minimap",
		description = "Also draw the destination's markers on the<br>"
			+ "minimap, where they will be once you land.",
		position = 4
	)
	default boolean showOnMinimap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "opacity",
		name = "Opacity",
		description = "How strongly the destination's tile markers are<br>"
			+ "drawn, compared with normal tile markers.",
		position = 5
	)
	@Range(min = 10, max = 100)
	@Units(Units.PERCENT)
	default int opacity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "lineThickness",
		name = "Line thickness",
		description = "How thick the destination's marker outlines are<br>"
			+ "drawn, in pixels. 0 uses the Tile Markers<br>plugin's border width.",
		position = 6
	)
	@Range(min = 0, max = 10)
	@Units(Units.PIXELS)
	default int lineThickness()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "blurRandom",
		name = "Blur random landings",
		description = "For teleports that land on a random tile near the<br>"
			+ "destination, draw the markers with a soft blur<br>"
			+ "around a sharp outline. They are placed as if<br>"
			+ "you land in the middle of the area. Other<br>"
			+ "teleports land exactly on their tile.",
		position = 7
	)
	default boolean blurRandom()
	{
		return true;
	}

	@ConfigItem(
		keyName = "blurDistance",
		name = "Blur distance",
		description = "How far the blur of random landings fades out<br>"
			+ "from each marker's outline, as a share of a<br>"
			+ "tile's width. The outline itself stays sharp.",
		position = 8
	)
	@Range(min = 5, max = 100)
	@Units(Units.PERCENT)
	default int blurDistance()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "hideUncertain",
		name = "Hide uncertain landings",
		description = "Don't show the markers for teleports that can<br>"
			+ "land the number of tiles below or more from<br>"
			+ "where they are drawn. Zones whose size isn't<br>known yet are still shown.",
		position = 9
	)
	default boolean hideUncertain()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideOffBy",
		name = "Hide when off by",
		description = "With Hide uncertain landings on: hide the markers<br>"
			+ "when the landing could be this many tiles or<br>more from where they are drawn.",
		position = 10
	)
	@Range(min = 1, max = 20)
	@Units(" tiles")
	default int hideOffBy()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "flashWhenLearned",
		name = "Flash when learned",
		description = "When a trip teaches the plugin something new<br>"
			+ "(your house's layout, an instance, the ground's<br>"
			+ "height, or where an item's last destination<br>"
			+ "goes), flash the destination's markers 3 times<br>"
			+ "when you land: in the override colour, or each<br>"
			+ "marker's own colour inverted.",
		position = 11
	)
	default boolean flashWhenLearned()
	{
		return true;
	}

	@ConfigItem(
		keyName = "learnHeights",
		name = "Learn ground height",
		description = "The first time you land somewhere, remember how<br>"
			+ "high the ground is under the marked tiles there.<br>"
			+ "Later trips draw each marker at its real height,<br>"
			+ "so hills and steps line up. Off: always flat.",
		position = 12
	)
	default boolean learnHeights()
	{
		return true;
	}

	@ConfigItem(
		keyName = FORGET_LEARNED,
		name = "Forget learned data",
		description = "Forget everything the plugin has learned on this<br>"
			+ "account: your house's layout, instances, ground<br>"
			+ "heights and items' last destinations. Asks first;<br>"
			+ "it can't be undone, and the next trip to each<br>"
			+ "place shows nothing (or flat markers) until it's<br>learned again.",
		position = 13,
		warning = "Forget everything Teleport Tile Markers has learned (your house's layout, instances, ground heights"
			+ " and items' last destinations)?\nThis can't be undone."
	)
	default boolean forgetLearned()
	{
		return false;
	}

	@ConfigSection(
		name = "Colours",
		description = "Draw the destination's markers in your own colours<br>"
			+ "instead of the Tile Markers ones. This only<br>"
			+ "changes how this plugin draws them; your tile<br>markers are never changed.",
		position = 14
	)
	String COLOURS = "colours";

	@ConfigItem(
		keyName = "overrideColour",
		name = "Override marker colour",
		description = "Draw every destination marker's outline and<br>label in the colour below.",
		position = 15,
		section = COLOURS
	)
	default boolean overrideColour()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "markerColour",
		name = "Marker colour",
		description = "The outline and label colour used when Override<br>marker colour is on.",
		position = 16,
		section = COLOURS
	)
	default Color markerColour()
	{
		return new Color(0, 200, 255, 255);
	}

	@ConfigItem(
		keyName = "overrideFill",
		name = "Override fill colour",
		description = "Fill every destination marker with the colour<br>below.",
		position = 17,
		section = COLOURS
	)
	default boolean overrideFill()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColour",
		name = "Fill colour",
		description = "The fill colour used when Override fill colour is<br>on.",
		position = 18,
		section = COLOURS
	)
	default Color fillColour()
	{
		return new Color(0, 200, 255, 10);
	}

	@ConfigItem(
		keyName = "overrideText",
		name = "Override text colour",
		description = "Draw every destination marker's label in the<br>colour below.",
		position = 19,
		section = COLOURS
	)
	default boolean overrideText()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "textColour",
		name = "Text colour",
		description = "The label colour used when Override text colour<br>is on.",
		position = 20,
		section = COLOURS
	)
	default Color textColour()
	{
		return Color.WHITE;
	}

	@ConfigSection(
		name = "Override threshold",
		description = "Only apply the colour overrides to some markers,<br>"
			+ "chosen by their own outline opacity.",
		position = 21
	)
	String THRESHOLD = "threshold";

	@ConfigItem(
		keyName = "overrideThreshold",
		name = "Override threshold",
		description = "Only apply the colour overrides to markers whose<br>"
			+ "own outline opacity is above, below or exactly<br>"
			+ "the threshold. With Override when set to Any,<br>the overrides apply to every marker.",
		position = 22,
		section = THRESHOLD
	)
	default boolean overrideThreshold()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overrideWhen",
		name = "Override when",
		description = "With Override threshold on: override markers<br>"
			+ "whose outline opacity is above, below or exactly<br>"
			+ "the threshold. Any overrides every marker and<br>ignores the threshold.",
		position = 23,
		section = THRESHOLD
	)
	default OverrideWhen overrideWhen()
	{
		return OverrideWhen.ANY;
	}

	@ConfigItem(
		keyName = "threshold",
		name = "Threshold",
		description = "The outline opacity (alpha, 0-255 as in the<br>"
			+ "colour pickers) that \"Override when\" compares<br>with.",
		position = 24,
		section = THRESHOLD
	)
	@Range(min = 0, max = 255)
	default int threshold()
	{
		// about 10%
		return 26;
	}
}

package com.teleportpretile;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The same preview on the minimap: each destination marker is drawn as many tiles from the player as it will be from them once they land, like the Tile Markers plugin draws its own tiles on
 * the minimap. A random landing is drawn fainter instead of blurred, since a minimap tile is only a few pixels.
 */
class TeleportPreTileMinimapOverlay extends Overlay
{
	private static final int HALF_TILE = Perspective.LOCAL_HALF_TILE_SIZE;
	/** How much fainter a random landing's tiles are drawn, as the 3D preview's fill is. */
	private static final double RANDOM_FAINT = 0.6;

	private final Client client;
	private final TeleportPreTileConfig config;
	private final TeleportPreTileOverlay overlay;

	@Inject
	TeleportPreTileMinimapOverlay(Client client, TeleportPreTileConfig config, TeleportPreTileOverlay overlay)
	{
		this.client = client;
		this.config = config;
		this.overlay = overlay;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showOnMinimap())
		{
			return null;
		}
		TeleportPreTilePlugin.Ghost ghost = overlay.shownGhost();
		if (ghost == null)
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		LocalPoint here = overlay.anchor();
		double opacity = config.opacity() / 100.0;
		if (config.blurRandom() && ghost.getTracker().getTeleport().isRandomLanding())
		{
			opacity *= RANDOM_FAINT;
		}

		Color defaultColor = overlay.style().defaultColor;
		for (GroundMarkerReader.Marker m : ghost.getMarkers())
		{
			// overrides only change how these preview markers are drawn; the Tile Markers data is only ever read
			Color color = overlay.outline(m.getColor() != null ? m.getColor() : defaultColor);
			fillTile(g, wv, here, m.getX() - ghost.getCenterX(), m.getY() - ghost.getCenterY(),
				TeleportPreTileOverlay.withAlpha(color, color.getAlpha() * opacity));
		}
		return null;
	}

	/** Fills the tile {@code dx}, {@code dy} tiles from the player on the minimap, if it is on the minimap. */
	private void fillTile(Graphics2D g, WorldView wv, LocalPoint here, int dx, int dy, Color color)
	{
		if (color.getAlpha() <= 0)
		{
			return;
		}
		int cx = here.getX() + dx * Perspective.LOCAL_TILE_SIZE;
		int cy = here.getY() + dy * Perspective.LOCAL_TILE_SIZE;
		Point sw = Perspective.localToMinimap(client, new LocalPoint(cx - HALF_TILE, cy - HALF_TILE, wv));
		Point nw = Perspective.localToMinimap(client, new LocalPoint(cx - HALF_TILE, cy + HALF_TILE, wv));
		Point ne = Perspective.localToMinimap(client, new LocalPoint(cx + HALF_TILE, cy + HALF_TILE, wv));
		Point se = Perspective.localToMinimap(client, new LocalPoint(cx + HALF_TILE, cy - HALF_TILE, wv));
		if (sw == null || nw == null || ne == null || se == null)
		{
			return; // off the minimap
		}
		Polygon poly = new Polygon();
		poly.addPoint(sw.getX(), sw.getY());
		poly.addPoint(nw.getX(), nw.getY());
		poly.addPoint(ne.getX(), ne.getY());
		poly.addPoint(se.getX(), se.getY());
		g.setColor(color);
		g.fill(poly);
	}
}

package com.teleportpretile;

import com.teleportpretile.data.Teleport;
import com.teleportpretile.render.Projector;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the destination's tile markers while the player teleports. The camera follows the player, so a tile N tiles
 * east of the landing spot will be drawn N tiles east of where the player stands once they land; each marker is
 * therefore drawn that far from the player now. The ground is taken as flat at the player's height.
 */
class TeleportPreTileOverlay extends Overlay
{
	private static final int TILE = Perspective.LOCAL_TILE_SIZE;
	private static final int HALF_TILE = Perspective.LOCAL_HALF_TILE_SIZE;
	/** JAU14 to radians, for the camera angles outside GPU mode. */
	private static final double JAU14 = 2 * Math.PI / 16384;
	/** How opaque the blur is right next to the outline, compared with the outline itself. */
	private static final double BLUR_PEAK = 0.6;
	/** Most layers one marker's blur is drawn with. */
	private static final int BLUR_LAYERS = 12;

	private final Client client;
	private final TeleportPreTilePlugin plugin;
	private final TeleportPreTileConfig config;
	private final ConfigManager configManager;

	@Inject
	TeleportPreTileOverlay(Client client, TeleportPreTilePlugin plugin, TeleportPreTileConfig config,
		ConfigManager configManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.configManager = configManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		renderLearned(g);
		return renderGhost(g);
	}

	/**
	 * After a trip on which the plugin saved something new, flash the destination's markers on their real tiles: drawn
	 * by this plugin on top, the player's tile markers are never changed.
	 */
	private void renderLearned(Graphics2D g)
	{
		TeleportPreTilePlugin.Learned learned = plugin.getLearned();
		long now = System.currentTimeMillis();
		if (learned == null || !config.flashWhenLearned() || !learned.getBlink().visible(now))
		{
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}
		Style style = style();
		Stroke stroke = new BasicStroke(style.width + 1);
		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (GroundMarkerReader.Marker m : learned.getMarkers())
		{
			if (m.getPlane() != wv.getPlane())
			{
				continue;
			}
			LocalPoint lp = learned.isSceneTiles() ? LocalPoint.fromScene(m.getX(), m.getY(), wv)
				: LocalPoint.fromWorld(wv, m.getX(), m.getY());
			Polygon poly = lp == null ? null : Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}
			Color own = m.getColor() != null ? m.getColor() : style.defaultColor;
			// with no colour override for this marker, flash in its own colour inverted, so it stands out from the
			// player's tile marker drawn on the same tile
			boolean overrideOutline = overridden(own) && config.overrideColour();
			boolean overrideFill = overridden(own) && config.overrideFill();
			Color color = overrideOutline ? config.markerColour() : inverted(own);
			g.setColor(overrideFill ? config.fillColour() : withAlpha(inverted(own), style.fillAlpha));
			g.fill(poly);
			g.setStroke(stroke);
			g.setColor(withAlpha(color, Math.max(color.getAlpha(), 160)));
			g.draw(poly);
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
	}

	/** The colour with its red, green and blue inverted (white for black, blue for yellow); alpha kept. */
	static Color inverted(Color c)
	{
		return new Color(255 - c.getRed(), 255 - c.getGreen(), 255 - c.getBlue(), c.getAlpha());
	}

	/** The Tile Markers plugin's look: default colour, border width (or this plugin's Line thickness) and fill opacity. */
	static final class Style
	{
		Color defaultColor;
		float width;
		int fillAlpha;
	}

	Style style()
	{
		Style s = new Style();
		Color defaultColor = configManager.getConfiguration(GroundMarkerReader.GROUP, "markerColor", Color.class);
		s.defaultColor = defaultColor == null ? Color.YELLOW : defaultColor;
		Double width = configManager.getConfiguration(GroundMarkerReader.GROUP, "borderWidth", Double.class);
		s.width = config.lineThickness() > 0 ? config.lineThickness() : width == null ? 2f : width.floatValue();
		Integer fillOpacity = configManager.getConfiguration(GroundMarkerReader.GROUP, "fillOpacity", Integer.class);
		s.fillAlpha = fillOpacity == null ? 50 : fillOpacity;
		return s;
	}

	/** Whether the colour overrides apply to a marker with this outline colour (see Override threshold). */
	private boolean overridden(Color own)
	{
		return !config.overrideThreshold() || config.overrideWhen().matches(own.getAlpha(), config.threshold());
	}

	/** The outline colour drawn for a marker of this colour; overrides change only this plugin's drawing. */
	Color outline(Color own)
	{
		return overridden(own) && config.overrideColour() ? config.markerColour() : own;
	}

	/** The label colour drawn for a marker of this colour, whose outline is drawn in {@code outline}. */
	Color label(Color own, Color outline)
	{
		return overridden(own) && config.overrideText() ? config.textColour() : withAlpha(outline, 255);
	}

	/** The fill colour drawn for a marker of this colour. */
	private Color fill(Color own, int fillAlpha)
	{
		return overridden(own) && config.overrideFill() ? config.fillColour() : new Color(0, 0, 0, fillAlpha);
	}

	/**
	 * The teleport preview to draw now, or null: nothing to show, not shown until the teleport starts (Show on click
	 * off), hidden as an uncertain landing, or the player isn't on the main map. Used by the minimap overlay too.
	 */
	TeleportPreTilePlugin.Ghost shownGhost()
	{
		TeleportPreTilePlugin.Ghost ghost = plugin.getGhost();
		if (ghost == null || ghost.getMarkers().isEmpty()
			|| (!config.showOnClick() && !ghost.getTracker().isStarted()))
		{
			return null;
		}
		Teleport teleport = ghost.getTracker().getTeleport();
		if (config.hideUncertain() && teleport.couldBeOffBy(config.hideOffBy()))
		{
			return null;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldView() == null || !player.getWorldView().isTopLevel()
			|| player.getLocalLocation() == null)
		{
			return null;
		}
		return ghost;
	}

	/**
	 * Where the preview is placed from: the player's true tile (the tile the server has them on) with Snap to true
	 * tile on, otherwise their smoothly moving position. Call only when {@link #shownGhost()} isn't null.
	 */
	LocalPoint anchor()
	{
		Player player = client.getLocalPlayer();
		LocalPoint smooth = player.getLocalLocation();
		if (!config.snapToTrueTile())
		{
			return smooth;
		}
		LocalPoint trueTile = LocalPoint.fromWorld(client.getTopLevelWorldView(), player.getWorldLocation());
		return trueTile != null ? trueTile : smooth;
	}

	private Dimension renderGhost(Graphics2D g)
	{
		TeleportPreTilePlugin.Ghost ghost = shownGhost();
		if (ghost == null)
		{
			return null;
		}
		LocalPoint here = anchor();

		int z = Perspective.getTileHeight(client, here, client.getTopLevelWorldView().getPlane());
		Projector projector = projector();
		Teleport teleport = ghost.getTracker().getTeleport();
		boolean blur = config.blurRandom() && teleport.isRandomLanding();
		double blurTiles = config.blurDistance() / 100.0;

		List<GroundMarkerReader.Marker> markers = ghost.getMarkers();

		double opacity = config.opacity() / 100.0;
		Style style = style();
		Color defaultColor = style.defaultColor;
		Stroke stroke = new BasicStroke(style.width);
		int fillAlpha = style.fillAlpha;

		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);


		for (GroundMarkerReader.Marker m : markers)
		{
			double dx = m.getX() - ghost.getCenterX();
			double dy = m.getY() - ghost.getCenterY();
			double cx = here.getX() + dx * TILE;
			double cy = here.getY() + dy * TILE;
			// overrides only change how these preview markers are drawn; the Tile Markers data is only ever read
			Color own = m.getColor() != null ? m.getColor() : defaultColor;
			Color color = outline(own);
			Color fill = fill(own, fillAlpha);

			int[] rise = ghost.getHeights() == null ? null
				: ghost.getHeights().at(m.getX() - ghost.getCenterX(), m.getY() - ghost.getCenterY());
			Polygon center = tile(projector, cx, cy, z, rise);
			if (center == null)
			{
				continue;
			}
			g.setColor(withAlpha(fill, fill.getAlpha() * opacity));
			g.fill(center);
			if (blur)
			{
				drawBlur(g, center, blurTiles * tileSize(center), color, opacity, style.width);
			}
			g.setStroke(stroke);
			g.setColor(withAlpha(color, color.getAlpha() * opacity));
			g.draw(center);
			if (m.getLabel() != null && !m.getLabel().isEmpty())
			{
				Color text = label(own, color);
				drawLabel(g, center, m.getLabel(), withAlpha(text, text.getAlpha() * opacity));
			}
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		return null;
	}

	/**
	 * A soft glow around the outline that fades out like a bell curve (a gaussian blur) over {@code reachPx} pixels on
	 * each side. It is drawn as the outline with ever narrower strokes on top of each other, the widest the faintest,
	 * with each stroke's opacity worked out so the piled-up strokes give the curve's opacity at that distance. The
	 * sharp outline is drawn over it afterwards.
	 */
	static void drawBlur(Graphics2D g, Polygon outline, double reachPx, Color color, double opacity, float lineWidth)
	{
		double[] a = blurLayerAlphas(reachPx);
		int n = a.length;
		int baseAlpha = color.getAlpha();
		for (int k = n; k >= 1; k--)
		{
			int alpha = (int) Math.round(baseAlpha * opacity * a[k - 1]);
			if (alpha <= 0)
			{
				continue;
			}
			float width = (float) (lineWidth + 2 * reachPx * k / n);
			g.setStroke(new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha));
			g.draw(outline);
		}
	}

	/**
	 * The opacity of each blur layer, nearest the outline first, for a blur reaching {@code reachPx} pixels. Layer k
	 * (of n) covers out to k/n of the reach, so the band between layers k-1 and k starts (k-1)/n of the reach out; the
	 * layers covering a band pile up to the bell curve's opacity at its start: peak * exp(-d²/2σ²) with σ a third of
	 * the reach, so it is strongest against the outline and has all but faded at the far edge.
	 */
	static double[] blurLayerAlphas(double reachPx)
	{
		int n = (int) Math.max(1, Math.min(BLUR_LAYERS, Math.round(reachPx / 1.5)));
		double sigma = 1 / 3.0;
		double[] target = new double[n + 2];
		for (int k = 1; k <= n; k++)
		{
			double d = (k - 1) / (double) n;
			target[k] = BLUR_PEAK * Math.exp(-0.5 * (d / sigma) * (d / sigma));
		}
		double[] a = new double[n];
		for (int k = n; k >= 1; k--)
		{
			// layers k..n together give target[k]: 1 - (1 - a_k)(1 - target[k + 1]) = target[k]
			a[k - 1] = Math.max(0, 1 - (1 - target[k]) / (1 - target[k + 1]));
		}
		return a;
	}

	/** Roughly how many pixels one tile is across on screen, from its drawn outline. */
	private static double tileSize(Polygon p)
	{
		double sum = 0;
		for (int i = 0; i < p.npoints; i++)
		{
			int j = (i + 1) % p.npoints;
			sum += Math.hypot(p.xpoints[j] - p.xpoints[i], p.ypoints[j] - p.ypoints[i]);
		}
		return sum / p.npoints;
	}

	private static Polygon tile(Projector projector, double cx, double cy, int z)
	{
		return tile(projector, cx, cy, z, null);
	}

	/**
	 * The tile's outline on screen, with its corners raised or lowered by {@code rise} (heights relative to the
	 * landing spot, in TileHeights' corner order), or flat at {@code z} when null.
	 */
	private static Polygon tile(Projector projector, double cx, double cy, int z, int[] rise)
	{
		int[] r = rise != null ? rise : new int[4];
		double[] sw = projector.project(cx - HALF_TILE, cy - HALF_TILE, z + r[0]);
		double[] nw = projector.project(cx + HALF_TILE, cy - HALF_TILE, z + r[1]);
		double[] ne = projector.project(cx + HALF_TILE, cy + HALF_TILE, z + r[2]);
		double[] se = projector.project(cx - HALF_TILE, cy + HALF_TILE, z + r[3]);
		if (sw == null || nw == null || ne == null || se == null)
		{
			return null;
		}
		Polygon p = new Polygon();
		p.addPoint((int) Math.round(sw[0]), (int) Math.round(sw[1]));
		p.addPoint((int) Math.round(nw[0]), (int) Math.round(nw[1]));
		p.addPoint((int) Math.round(ne[0]), (int) Math.round(ne[1]));
		p.addPoint((int) Math.round(se[0]), (int) Math.round(se[1]));
		return p;
	}

	private static void drawLabel(Graphics2D g, Polygon tile, String label, Color color)
	{
		int sx = 0;
		int sy = 0;
		for (int i = 0; i < tile.npoints; i++)
		{
			sx += tile.xpoints[i];
			sy += tile.ypoints[i];
		}
		FontMetrics fm = g.getFontMetrics();
		int x = sx / tile.npoints - fm.stringWidth(label) / 2;
		int y = sy / tile.npoints + fm.getAscent() / 2;
		g.setColor(withAlpha(Color.BLACK, color.getAlpha()));
		g.drawString(label, x + 1, y + 1);
		g.setColor(color);
		g.drawString(label, x, y);
	}

	private Projector projector()
	{
		if (client.isGpu())
		{
			return new Projector(client.getCameraFpX(), client.getCameraFpY(), client.getCameraFpZ(),
				client.getCameraFpPitch(), client.getCameraFpYaw(), client.getScale(), client.getViewportWidth(),
				client.getViewportHeight(), client.getViewportXOffset(), client.getViewportYOffset());
		}
		return new Projector(client.getCameraX(), client.getCameraY(), client.getCameraZ(),
			client.getCameraPitch() * JAU14, client.getCameraYaw() * JAU14, client.getScale(),
			client.getViewportWidth(), client.getViewportHeight(), client.getViewportXOffset(),
			client.getViewportYOffset());
	}

	static Color withAlpha(Color c, double alpha)
	{
		int a = (int) Math.round(Math.max(0, Math.min(255, alpha)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}
}

