@Slf4j
@PluginDescriptor(
	name = "Teleport Tile Markers",
	description = "Shows the tile markers at a teleport's destination while you are still teleporting",
	tags = {"teleport", "tile", "marker", "ground", "destination", "pre"}
)
public class TeleportPreTilePlugin extends Plugin implements KeyListener
{
	/** Game ticks a dialog or list opened by a teleport item stays open for the choice to count. */
	private static final int CHOICE_TICKS = 100;
	/** A landing further than this from the teleport's destination (in tiles) wasn't that teleport. */
	private static final int LANDING_TILES = 12;
	private static final int HALF_TILE = Perspective.LOCAL_HALF_TILE_SIZE;

	/**
	 * The teleport in progress and the destination markers to draw for it, placed around (centerX, centerY), the tile
	 * the player will land on. For the house or another instance these are scene tiles of it as last seen, not
	 * world tiles. {@code heights}: the ground's height at the markers, learned on an earlier trip; null to draw them
	 * flat.
	 */
	@Value
	static class Ghost
	{
		TeleportTracker tracker;
		List<GroundMarkerReader.Marker> markers;
		int centerX;
		int centerY;
		TileHeights heights;
	}


	/**
	 * The destination's markers flashing on their real tiles after a trip on which the plugin learned something (the
	 * house's layout, what a "last destination" means), so the player sees it was saved. Markers in world tiles, or
	 * scene tiles for the house.
	 */
	@Value
	static class Learned
	{
		List<GroundMarkerReader.Marker> markers;
		boolean sceneTiles;
		Blink blink;
	}

	/** Per-account config key for the player's house as last seen (see HouseLayout). */
	private static final String HOUSE_KEY = "houseLayout";
	/**
	 * Per-account config key prefix, then a teleport's id, for the instance that teleport landed in last time (a
	 * HouseLayout with one entry): most instances are built the same way every time, so the player's markers in it
	 * can be placed before arriving, as for the house.
	 */
	private static final String INSTANCE_PREFIX = "instance.";
	private static final String INSTANCE_ENTRY = "arrival";
	/**
	 * Per-account config key prefix, then a landing tile "x_y_plane", for the ground's height at the marked tiles
	 * around it (see TileHeights), learned on arrival.
	 */
	private static final String HEIGHTS_PREFIX = "heights.";

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private KeyManager keyManager;
	@Inject
	private ConfigManager configManager;
	@Inject
	private TeleportPreTileConfig config;
	@Inject
	private TeleportPreTileOverlay overlay;
	@Inject
	private TeleportPreTileMinimapOverlay minimapOverlay;
	@Inject
	private GroundMarkerReader groundMarkers;
	@Inject
	private Gson gson;


	private TeleportCatalog catalog;

	/** Read by the overlay on the render thread. */
	@Getter
	private volatile Ghost ghost;
	/** Read by the overlay on the render thread. */
	@Getter
	private volatile Learned learned;
	private boolean spotAnimSeen;

	/** Teleports whose dialog or list is open ("Rub" on a glory), waiting for the destination to be picked. */
	private volatile List<Teleport> opened = Collections.emptyList();
	private int openedTick;
	/**
	 * The open chat dialog's texts by child index, and the open list's entries, for picking one with a key; read on
	 * the key thread.
	 */
	private volatile String[] chatEntries;
	private volatile List<String> listEntries = Collections.emptyList();

	@Provides
	TeleportPreTileConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TeleportPreTileConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		if (catalog == null)
		{
			try (InputStream in = TeleportPreTilePlugin.class.getResourceAsStream("teleports.tsv"))
			{
				if (in == null)
				{
					throw new IOException("teleports.tsv is missing from the plugin");
				}
				catalog = TeleportCatalog.load(in);
			}
			log.debug("loaded {} teleports", catalog.all().size());
		}
		overlayManager.add(overlay);
		overlayManager.add(minimapOverlay);
		keyManager.registerKeyListener(this);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(minimapOverlay);
		keyManager.unregisterKeyListener(this);
		ghost = null;
		learned = null;
		settling = null;
		clearOpened();
		groundMarkers.invalidate();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		String option = e.getMenuOption();
		int itemId = e.getItemId();
		String target = ClickedName.of(e.getMenuTarget(),
			() -> itemId > 0 ? client.getItemDefinition(itemId).getName() : null,
			() -> e.getWidget() != null ? e.getWidget().getName() : null,
			() -> objectName(e),
			() -> e.getMenuEntry().getNpc() != null ? e.getMenuEntry().getNpc().getName() : null);

		Ghost g = ghost;
		if (g != null && g.getTracker().getTeleport().getKind() != Teleport.Kind.TELEPORT
			&& Text.clean(option).equalsIgnoreCase("Walk here"))
		{
			// walked off instead of boarding; a teleport is kept, as the player may click ahead where they will land
			ghost = null;
		}

		// fairy rings: the dials' code, sent with the interface's Confirm button, or a ring's own option
		String ring = e.getParam1() == InterfaceID.Fairyrings.CONFIRM
			? FairyRings.code(client.getVarbitValue(VarbitID.FAIRYRING_1), client.getVarbitValue(VarbitID.FAIRYRING_2),
				client.getVarbitValue(VarbitID.FAIRYRING_3))
			: FairyRings.codeOfOption(option, target);
		if (ring != null)
		{
			begin(catalog.fairyRing(ring));
			return;
		}

		if (!opened.isEmpty())
		{
			List<String> texts = new ArrayList<>(4);
			texts.add(option);
			texts.add(target);
			Widget w = e.getWidget();
			if (w != null && w.getText() != null)
			{
				texts.add(w.getText());
			}
			if (w != null && w.getName() != null)
			{
				texts.add(w.getName());
			}
			texts.addAll(rowTexts(e.getParam1(), e.getParam0()));
			for (String text : texts)
			{
				List<Teleport> chosen = TeleportCatalog.chosen(opened, text);
				if (!chosen.isEmpty())
				{
					begin(chosen);
					return;
				}
			}
		}

		LastDestination last = LastDestination.clicked(option, target);
		if (last != null)
		{
			Teleport t = catalog.byId(configManager.getConfiguration(TeleportPreTileConfig.GROUP,
				TeleportPreTileConfig.LAST_DESTINATION_PREFIX + last.key(client.getVarbitValue(last.getVarbit()))));
			if (t != null)
			{
				begin(Collections.singletonList(t));
			}
			return;
		}

		List<Teleport> started = nearPlayer(catalog.started(option, target, itemId));
		if (!started.isEmpty())
		{
			begin(started);
			return;
		}

		List<Teleport> opens = nearPlayer(catalog.opened(option, target, itemId));
		if (!opens.isEmpty())
		{
			opened = opens;
			openedTick = client.getTickCount();
			log.debug("click opened {} teleports: '{}' '{}' item {}", opens.size(), option, target, itemId);
			return;
		}
		if (log.isDebugEnabled())
		{
			// what wasn't taken for a teleport, to find clicks the data names differently from the game
			Widget w = e.getWidget();
			log.debug("click not a teleport: '{}' '{}' item {} id {} p0 {} p1 {} widget text '{}' name '{}'{}", option,
				target, itemId, e.getId(), e.getParam0(), e.getParam1(), w == null ? null : w.getText(),
				w == null ? null : w.getName(), opened.isEmpty() ? "" : " (a list of " + opened.size() + " is open)");
		}
	}

	/** The clicked object's name (as the player sees it, for objects that change with varbits), or null. */
	private String objectName(MenuOptionClicked e)
	{
		if (!e.getMenuAction().name().startsWith("GAME_OBJECT_"))
		{
			return null;
		}
		ObjectComposition def = client.getObjectDefinition(e.getId());
		if (def != null && def.getImpostorIds() != null)
		{
			ObjectComposition shown = def.getImpostor();
			def = shown != null ? shown : def;
		}
		return def != null ? def.getName() : null;
	}

	/** Picking a dialog option or list entry with its key, as most players do. */
	@Override
	public void keyPressed(KeyEvent e)
	{
		if (opened.isEmpty())
		{
			return;
		}
		char c = e.getKeyChar();
		// a key the game's list fixes for a choice (the house jewellery box, spirit trees) picks it outright
		List<Teleport> keyed = TeleportCatalog.chosenByKey(opened, c);
		if (!keyed.isEmpty())
		{
			clientThread.invoke(() -> begin(keyed));
			return;
		}
		// either kind may be a leftover from an earlier dialog: the one whose entry is a choice of the opened item wins
		String chat = DialogKeys.chatOption(chatEntries, c);
		String list = DialogKeys.listEntry(listEntries, c);
		if (chat == null && list == null)
		{
			return;
		}
		clientThread.invoke(() ->
		{
			for (String entry : new String[]{chat, list})
			{
				List<Teleport> chosen = entry == null ? Collections.emptyList() : TeleportCatalog.chosen(opened, entry);
				if (!chosen.isEmpty())
				{
					begin(chosen);
					return;
				}
			}
		});
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}

	@Subscribe
	public void onClientTick(ClientTick e)
	{
		if (opened.isEmpty())
		{
			return;
		}
		// Keep the open dialog's entries ready for the key listener, which runs off the client thread and may run
		// after the game has already closed the dialog.
		String[] chat = byIndex(client.getWidget(InterfaceID.Chatmenu.OPTIONS));
		if (chat != null)
		{
			chatEntries = chat;
		}
		List<String> list = texts(client.getWidget(InterfaceID.Menu.LJ_LAYER1));
		if (list.isEmpty())
		{
			list = texts(client.getWidget(InterfaceID.TelenexusTeleport.TEXT1));
		}
		if (!list.isEmpty())
		{
			listEntries = list;
		}
	}

	/**
	 * The texts shown on the row clicked in a list whose rows are blank click boxes with the texts in a layer of
	 * their own, as in the house portal nexus: the clicked row's own child, and the texts level with it.
	 */
	private List<String> rowTexts(int widgetId, int row)
	{
		List<String> out = new ArrayList<>();
		if (widgetId != InterfaceID.TelenexusTeleport.ROWS1 || row < 0)
		{
			return out;
		}
		Widget rows = client.getWidget(widgetId);
		Widget clicked = rows == null ? null : rows.getChild(row);
		Widget[] texts = children(client.getWidget(InterfaceID.TelenexusTeleport.TEXT1));
		if (texts == null)
		{
			return out;
		}
		if (row < texts.length && texts[row] != null && texts[row].getText() != null)
		{
			out.add(texts[row].getText());
		}
		if (clicked != null)
		{
			int top = clicked.getRelativeY();
			int bottom = top + Math.max(clicked.getHeight(), 1);
			for (Widget t : texts)
			{
				int mid = t == null ? -1 : t.getRelativeY() + t.getHeight() / 2;
				if (t != null && t.getText() != null && mid >= top && mid < bottom)
				{
					out.add(t.getText());
				}
			}
		}
		log.debug("portal nexus row {}: {}", row, out);
		return out;
	}

	private static Widget[] children(Widget parent)
	{
		if (parent == null || parent.isHidden())
		{
			return null;
		}
		return parent.getDynamicChildren();
	}

	/** The children's texts by child index (null where a child has no text), or null when there are none. */
	private static String[] byIndex(Widget parent)
	{
		Widget[] children = children(parent);
		if (children == null || children.length == 0)
		{
			return null;
		}
		String[] out = new String[children.length];
		boolean any = false;
		for (Widget w : children)
		{
			String t = w == null ? null : Text.clean(w.getText());
			if (t != null && !t.isEmpty() && w.getIndex() >= 0 && w.getIndex() < out.length)
			{
				out[w.getIndex()] = t;
				any = true;
			}
		}
		return any ? out : null;
	}

	private static List<String> texts(Widget parent)
	{
		Widget[] children = children(parent);
		if (children == null)
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>(children.length);
		for (Widget w : children)
		{
			String t = w == null ? null : Text.clean(w.getText());
			if (t != null && !t.isEmpty())
			{
				out.add(t);
			}
		}
		return out;
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged e)
	{
		if (ghost != null && e.getActor() == client.getLocalPlayer())
		{
			spotAnimSeen = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		int tick = client.getTickCount();
		if (!opened.isEmpty() && tick - openedTick > CHOICE_TICKS)
		{
			clearOpened();
		}

		if (settling != null)
		{
			settle(tick);
		}

		Ghost g = ghost;
		Player player = client.getLocalPlayer();
		if (g == null || player == null)
		{
			return;
		}
		WorldPoint at = player.getWorldLocation();
		TeleportTracker.Result result = g.getTracker().tick(tick, at.getX(), at.getY(), at.getPlane(),
			player.getAnimation(), spotAnimSeen);
		if (result == TeleportTracker.Result.ARRIVED)
		{
			ghost = null;
			Teleport t = g.getTracker().getTeleport();
			if (rememberLastDestination(g.getTracker()))
			{
				learned = new Learned(markersFor(t), false, new Blink(System.currentTimeMillis()));
			}
			// the house (and other instances) may first put the player somewhere while it loads and move them a tick
			// or two later: the arrival tile is taken once they stay put
			settling = new Settling(t, t.isHouse() ? HOUSE_KEY : INSTANCE_PREFIX + t.getId(),
				t.isHouse() ? t.getHouseEntry() : INSTANCE_ENTRY, !t.isHouse(), tick);
			settle(tick);
		}
		else if (result == TeleportTracker.Result.CANCELLED)
		{
			ghost = null;
		}
	}

	/** A trip's arrival waiting for the player to stay put before the instance and arrival tile are remembered. */
	private static final class Settling
	{
		final Teleport teleport;
		final String key;
		final String entry;
		final boolean forgetIfNot;
		final int startTick;
		int lastX = Integer.MIN_VALUE;
		int lastY = Integer.MIN_VALUE;
		int lastPlane = -1;
		int stillTicks;

		Settling(Teleport teleport, String key, String entry, boolean forgetIfNot, int startTick)
		{
			this.teleport = teleport;
			this.key = key;
			this.entry = entry;
			this.forgetIfNot = forgetIfNot;
			this.startTick = startTick;
		}
	}

	/**
	 * Ticks the player must stay on one tile after arriving for that to be the arrival tile. In game the house puts the
	 * player on a loading tile for one tick and then on the real one, so one still tick is enough.
	 */
	private static final int SETTLE_TICKS = 1;
	/** Gives up on settling after this many ticks (the player walked straight off). */
	private static final int SETTLE_MAX_TICKS = 8;

	private Settling settling;

	private void settle(int tick)
	{
		Settling st = settling;
		Player player = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (st == null || player == null || wv == null || player.getLocalLocation() == null
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		LocalPoint lp = player.getLocalLocation();
		int x = lp.getSceneX();
		int y = lp.getSceneY();
		int plane = wv.getPlane();
		log.debug("{} ({}): tick {} after arriving, scene tile {},{} plane {}{}", st.key, st.entry, tick - st.startTick,
			x, y, plane, wv.isInstance() ? " (instance)" : "");
		boolean jumped = st.lastPlane != plane || Math.max(Math.abs(x - st.lastX), Math.abs(y - st.lastY)) > 0;
		st.lastX = x;
		st.lastY = y;
		st.lastPlane = plane;
		st.stillTicks = jumped ? 0 : st.stillTicks + 1;
		if (st.stillTicks < SETTLE_TICKS && tick - st.startTick < SETTLE_MAX_TICKS)
		{
			return;
		}
		settling = null;
		if (st.stillTicks < SETTLE_TICKS)
		{
			log.debug("{} ({}): the player kept moving after arriving; not saved", st.key, st.entry);
			return;
		}
		if (!st.teleport.isHouse() && !wv.isInstance())
		{
			learnHeights(st.teleport, wv);
		}
		if (rememberInstance(st.key, st.entry, st.forgetIfNot))
		{
			HouseLayout layout = loadLayout(st.key);
			int[] arrivedAt = layout == null ? null : layout.entry(st.entry);
			if (arrivedAt != null)
			{
				learned = new Learned(houseMarkers(layout, arrivedAt), true, new Blink(System.currentTimeMillis()));
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState s = e.getGameState();
		if (s == GameState.LOGIN_SCREEN || s == GameState.HOPPING || s == GameState.CONNECTION_LOST)
		{
			ghost = null;
			learned = null;
			settling = null;
			clearOpened();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (GroundMarkerReader.GROUP.equals(e.getGroup()) && e.getKey().startsWith("region_"))
		{
			groundMarkers.invalidate();
			refreshMarkers();
		}
		else if (TeleportPreTileConfig.GROUP.equals(e.getGroup())
			&& ("drawDistance".equals(e.getKey()) || "learnHeights".equals(e.getKey())))
		{
			refreshMarkers();
		}
		else if (TeleportPreTileConfig.GROUP.equals(e.getGroup()) && TeleportPreTileConfig.FORGET_LEARNED.equals(e.getKey())
			&& "true".equals(e.getNewValue()))
		{
			// the panel has already asked (the setting's warning); forget, then untick the box again
			clientThread.invoke(this::forgetLearned);
		}
	}

	/**
	 * Forgets everything learned on trips for this account: the house's layout, the instances, the ground's heights,
	 * and what each item's "last destination" means. The player's tile markers are not touched.
	 */
	private void forgetLearned()
	{
		String group = TeleportPreTileConfig.GROUP;
		int forgotten = 0;
		String profile = configManager.getRSProfileKey();
		if (profile != null)
		{
			for (String key : configManager.getRSProfileConfigurationKeys(group, profile, ""))
			{
				if (key.equals(HOUSE_KEY) || key.startsWith(INSTANCE_PREFIX) || key.startsWith(HEIGHTS_PREFIX))
				{
					configManager.unsetRSProfileConfiguration(group, key);
					forgotten++;
				}
			}
		}
		for (String full : configManager.getConfigurationKeys(group + "." + TeleportPreTileConfig.LAST_DESTINATION_PREFIX))
		{
			configManager.unsetConfiguration(group, full.substring(group.length() + 1));
			forgotten++;
		}
		ghost = null;
		learned = null;
		settling = null;
		// untick the box again; an open settings panel shows it unticked once it is reopened
		configManager.setConfiguration(group, TeleportPreTileConfig.FORGET_LEARNED, false);
		log.debug("forgot {} learned entries", forgotten);
	}

	/** The candidates with the rides boarded somewhere else than near the player left out. */
	private List<Teleport> nearPlayer(List<Teleport> candidates)
	{
		Player player = client.getLocalPlayer();
		if (player == null || candidates.isEmpty())
		{
			return candidates;
		}
		WorldPoint at = player.getWorldLocation();
		return TeleportCatalog.near(candidates, at.getX(), at.getY(), at.getPlane());
	}

	/** Starts showing the destination of the one teleport these candidates resolve to, if they resolve. */
	private void begin(List<Teleport> candidates)
	{
		clearOpened();
		Teleport t = TeleportCatalog.resolve(candidates, client::getVarbitValue);
		Player player = client.getLocalPlayer();
		if (t == null || player == null)
		{
			return;
		}
		WorldPoint at = player.getWorldLocation();
		TeleportTracker tracker = new TeleportTracker(t, client.getTickCount(), at.getX(), at.getY(), at.getPlane(),
			player.getAnimation());
		spotAnimSeen = false;
		learned = null;
		settling = null;
		ghost = ghostFor(tracker);
		log.debug("teleport {} to {},{},{}", t.getName(), t.getX(), t.getY(), t.getPlane());
	}

	/** The markers to draw for this trip and the tile they are placed around. */
	private Ghost ghostFor(TeleportTracker tracker)
	{
		Teleport t = tracker.getTeleport();
		if (!t.isHouse())
		{
			// a teleport into an instance: the instance as it was last time, if it went to one before
			HouseLayout instance = loadLayout(INSTANCE_PREFIX + t.getId());
			int[] at = instance == null ? null : instance.entry(INSTANCE_ENTRY);
			if (at != null)
			{
				List<GroundMarkerReader.Marker> markers = houseMarkers(instance, at);
				log.debug("instance: {} markers around scene tile {},{} plane {}", markers.size(), at[0], at[1], at[2]);
				return new Ghost(tracker, markers, at[0], at[1], null);
			}
			return new Ghost(tracker, markersFor(t), t.getX(), t.getY(), loadHeights(t));
		}
		// the house: the markers of the house as last seen, around the tile the player arrived on then. The first
		// trip shows nothing (tracked all the same, so the layout is learned when the player lands)
		HouseLayout house = loadLayout(HOUSE_KEY);
		int[] at = house == null ? null : house.entry(t.getHouseEntry());
		if (at == null)
		{
			log.debug("house ({}): layout not seen yet, learning it on arrival", t.getHouseEntry());
			return new Ghost(tracker, Collections.emptyList(), 0, 0, null);
		}
		List<GroundMarkerReader.Marker> markers = houseMarkers(house, at);
		log.debug("house ({}): {} markers around scene tile {},{} plane {}", t.getHouseEntry(), markers.size(), at[0],
			at[1], at[2]);
		return new Ghost(tracker, markers, at[0], at[1], null);
	}

	/**
	 * The player's marked tiles in the house, as scene tiles of the house as last seen: each marker is saved at its
	 * room template's tile, and shows wherever that template is placed (as the Tile Markers plugin draws them).
	 */
	private List<GroundMarkerReader.Marker> houseMarkers(HouseLayout house, int[] at)
	{
		int range = config.drawDistance();
		List<GroundMarkerReader.Marker> out = new ArrayList<>();
		for (HouseLayout.Placement p : house.placements(at[2]))
		{
			for (GroundMarkerReader.Marker m : groundMarkers.around(p.templateX + 3, p.templateY + 3, p.templatePlane, 4))
			{
				if (!p.holds(m.getX(), m.getY(), m.getPlane()))
				{
					continue;
				}
				int[] scene = p.toScene(m.getX(), m.getY());
				if (Math.abs(scene[0] - at[0]) <= range && Math.abs(scene[1] - at[1]) <= range)
				{
					out.add(new GroundMarkerReader.Marker(scene[0], scene[1], at[2], m.getColor(), m.getLabel()));
				}
			}
		}
		return out;
	}

	private HouseLayout loadLayout(String key)
	{
		String json = configManager.getRSProfileConfiguration(TeleportPreTileConfig.GROUP, key);
		if (json == null)
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, HouseLayout.class);
		}
		catch (JsonParseException e)
		{
			log.debug("unreadable house layout", e);
			return null;
		}
	}

	/**
	 * After landing in an instance (the house, or any other a teleport goes to): remember its layout (the instance's
	 * template chunks) and where the player arrived for this entry, for the next trip's preview. Saved per account; a
	 * rebuilt house, or an instance built differently, starts afresh.
	 *
	 * @param forgetIfNot when not landing in an instance, forget what was saved (the teleport no longer goes to one)
	 * @return true when something new was saved (a new or rebuilt layout, or a new arrival tile)
	 */
	private boolean rememberInstance(String key, String entry, boolean forgetIfNot)
	{
		WorldView wv = client.getTopLevelWorldView();
		Player player = client.getLocalPlayer();
		if (wv == null || player == null || player.getLocalLocation() == null)
		{
			return false;
		}
		if (!wv.isInstance())
		{
			if (forgetIfNot && configManager.getRSProfileConfiguration(TeleportPreTileConfig.GROUP, key) != null)
			{
				configManager.unsetRSProfileConfiguration(TeleportPreTileConfig.GROUP, key);
			}
			return false;
		}
		int[][][] chunks = wv.getInstanceTemplateChunks();
		HouseLayout house = loadLayout(key);
		if (house == null || !house.sameChunks(chunks))
		{
			house = new HouseLayout(chunks);
		}
		LocalPoint at = player.getLocalLocation();
		int[] before = house.entry(entry);
		int[] now = {at.getSceneX(), at.getSceneY(), wv.getPlane()};
		if (java.util.Arrays.equals(before, now))
		{
			return false;
		}
		house.arrived(entry, now[0], now[1], now[2]);
		configManager.setRSProfileConfiguration(TeleportPreTileConfig.GROUP, key, gson.toJson(house));
		log.debug("{} ({}): layout saved, {} room chunks on plane {}, arrived at scene tile {},{}", key, entry,
			house.placements(wv.getPlane()).size(), wv.getPlane(), at.getSceneX(), at.getSceneY());
		return true;
	}

	private List<GroundMarkerReader.Marker> markersFor(Teleport t)
	{
		return groundMarkers.around(t.getX(), t.getY(), t.getPlane(), config.drawDistance());
	}

	private static String heightsKey(Teleport t)
	{
		return HEIGHTS_PREFIX + t.getX() + "_" + t.getY() + "_" + t.getPlane();
	}

	/** The ground's heights at this teleport's landing spot from an earlier trip, or null (draw flat). */
	private TileHeights loadHeights(Teleport t)
	{
		if (!config.learnHeights())
		{
			return null;
		}
		return TileHeights.decode(configManager.getRSProfileConfiguration(TeleportPreTileConfig.GROUP, heightsKey(t)));
	}

	/**
	 * Just landed from this teleport on the main map and stayed put: remember the ground's height under the marked
	 * tiles around its landing spot, for the next trip. Done on every trip, so markers added since are learned too.
	 */
	private void learnHeights(Teleport t, WorldView wv)
	{
		Player player = client.getLocalPlayer();
		if (!config.learnHeights() || player == null)
		{
			return;
		}
		WorldPoint at = player.getWorldLocation();
		if (at.getPlane() != t.getPlane()
			|| Math.max(Math.abs(at.getX() - t.getX()), Math.abs(at.getY() - t.getY())) > LANDING_TILES)
		{
			return;
		}
		List<GroundMarkerReader.Marker> markers = markersFor(t);
		int[][] marked = new int[markers.size()][];
		for (int i = 0; i < marked.length; i++)
		{
			marked[i] = new int[]{markers.get(i).getX(), markers.get(i).getY()};
		}
		int plane = t.getPlane();
		TileHeights heights = TileHeights.learn(t.getX(), t.getY(), marked, (x, y, corner) ->
		{
			LocalPoint lp = LocalPoint.fromWorld(wv, x, y);
			if (lp == null)
			{
				return null;
			}
			int lx = lp.getX() + (corner == 1 || corner == 2 ? HALF_TILE : -HALF_TILE);
			int ly = lp.getY() + (corner >= 2 ? HALF_TILE : -HALF_TILE);
			if (lx < 0 || ly < 0 || (lx >> 7) >= wv.getSizeX() || (ly >> 7) >= wv.getSizeY())
			{
				return null;
			}
			return Perspective.getTileHeight(client, new LocalPoint(lx, ly, wv), plane);
		});
		if (heights == null)
		{
			return;
		}
		String value = heights.encode();
		String key = heightsKey(t);
		String saved = configManager.getRSProfileConfiguration(TeleportPreTileConfig.GROUP, key);
		if (!value.equals(saved))
		{
			configManager.setRSProfileConfiguration(TeleportPreTileConfig.GROUP, key, value);
			log.debug("{}: heights of {} raised or sloped marked tiles saved", key, heights.size());
		}
		if (heights.addsTo(TileHeights.decode(saved)))
		{
			// a height the next trip will use that it didn't know: flash the markers, as for other things learned
			learned = new Learned(markers, false, new Blink(System.currentTimeMillis()));
		}
	}

	private void refreshMarkers()
	{
		clientThread.invoke(() ->
		{
			Ghost g = ghost;
			if (g != null)
			{
				ghost = ghostFor(g.getTracker());
			}
		});
	}

	/**
	 * After landing from a teleport of an item with a "last destination" option, the item's varbit holds this
	 * destination: remember which teleport that value means (see {@link LastDestination}).
	 */
	/** @return true when a new meaning of the item's "last destination" value was saved */
	private boolean rememberLastDestination(TeleportTracker tracker)
	{
		Teleport t = tracker.getTeleport();
		LastDestination last = LastDestination.of(t);
		if (last == null || client.getTopLevelWorldView().isInstance() || tracker.getArrivalPlane() != t.getPlane()
			|| Math.max(Math.abs(tracker.getArrivalX() - t.getX()), Math.abs(tracker.getArrivalY() - t.getY())) > LANDING_TILES)
		{
			return false;
		}
		int value = client.getVarbitValue(last.getVarbit());
		if (value == 0)
		{
			return false;
		}
		String key = TeleportPreTileConfig.LAST_DESTINATION_PREFIX + last.key(value);
		if (t.getId().equals(configManager.getConfiguration(TeleportPreTileConfig.GROUP, key)))
		{
			return false;
		}
		configManager.setConfiguration(TeleportPreTileConfig.GROUP, key, t.getId());
		return true;
	}

	private void clearOpened()
	{
		opened = Collections.emptyList();
		chatEntries = null;
		listEntries = Collections.emptyList();
	}
}

package com.teleportpretile.data;

import java.util.Arrays;
import java.util.function.Supplier;

/**
 * The name of what a click was on. Entries in a right-click sub-menu ("Rub" then "Edgeville" on a glory in the
 * inventory, "Teleports" then a place on a worn Max cape, "Favourites" then a code on a fairy ring) come with an
 * empty target, so the name is found from the clicked item, interface slot, object or NPC instead.
 */
public final class ClickedName
{
	private ClickedName()
	{
	}

	/**
	 * The menu target when it has text, else the first of the others that has: the item's name, the interface slot's
	 * name, the object's name, the NPC's name. Each is only asked for when needed; any may give null.
	 */
	public static String of(String target, Supplier<String> item, Supplier<String> widget, Supplier<String> object,
		Supplier<String> npc)
	{
		if (!Text.clean(target).isEmpty())
		{
			return target;
		}
		for (Supplier<String> s : Arrays.asList(item, widget, object, npc))
		{
			String name = s.get();
			if (!Text.clean(name).isEmpty())
			{
				return name;
			}
		}
		return target == null ? "" : target;
	}
}

package com.teleportpretile.data;

import java.util.function.IntUnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.gameval.VarbitID;

/**
 * A requirement the plugin can check from varbits, used to pick between teleports that share a click (the Arceuus
 * Respawn Teleport goes wherever the respawn point is; Teleport to House goes to the house's portal).
 */
@Value
public class Condition
{
	/** Varbit SPELLBOOK: 0 standard, 1 ancient, 2 lunar, 3 arceuus. */
	static final int SPELLBOOK_VARBIT = VarbitID.SPELLBOOK;
	/** Varbit POH_HOUSE_LOCATION. */
	static final int HOUSE_VARBIT = VarbitID.POH_HOUSE_LOCATION;

	private static final Pattern VARBIT = Pattern.compile("^varbit (\\d+) (=|!=|<|<=|>|>=) (-?\\d+)$");
	private static final String[] SPELLBOOKS = {"standard", "ancient", "lunar", "arceuus"};
	/** Varbit 2187 values to house places (the game's enum 252), as Best Path names them. */
	private static final String[] HOUSES = new String[14];

	static
	{
		HOUSES[1] = "rimmington";
		HOUSES[2] = "taverley";
		HOUSES[3] = "pollnivneach";
		HOUSES[4] = "rellekka";
		HOUSES[5] = "brimhaven";
		HOUSES[6] = "yanille";
		HOUSES[8] = "hosidius";
		HOUSES[9] = "prifddinas";
		HOUSES[13] = "aldarin";
	}

	int varbit;
	String op;
	int value;

	/** Parses one condition from the data; null when the plugin can't check it. */
	public static Condition parse(String s)
	{
		String t = s.trim().toLowerCase();
		Matcher m = VARBIT.matcher(t);
		if (m.matches())
		{
			return new Condition(Integer.parseInt(m.group(1)), m.group(2), Integer.parseInt(m.group(3)));
		}
		if (t.startsWith("spellbook "))
		{
			int book = indexOf(SPELLBOOKS, t.substring("spellbook ".length()));
			return book < 0 ? null : new Condition(SPELLBOOK_VARBIT, "=", book);
		}
		if (t.startsWith("house at "))
		{
			int house = indexOf(HOUSES, t.substring("house at ".length()));
			return house < 0 ? null : new Condition(HOUSE_VARBIT, "=", house);
		}
		return null;
	}

	private static int indexOf(String[] names, String name)
	{
		for (int i = 0; i < names.length; i++)
		{
			if (name.equals(names[i]))
			{
				return i;
			}
		}
		return -1;
	}

	public boolean test(IntUnaryOperator varbits)
	{
		int v = varbits.applyAsInt(varbit);
		switch (op)
		{
			case "=":
				return v == value;
			case "!=":
				return v != value;
			case "<":
				return v < value;
			case "<=":
				return v <= value;
			case ">":
				return v > value;
			case ">=":
				return v >= value;
			default:
				return true;
		}
	}
}

package com.teleportpretile.data;

import java.util.List;

/**
 * Which entry a key picks in the game's two kinds of teleport choice, as the game's scripts build them:
 * <ul>
 * <li>The chat dialog ("Select an Option", script chatbox_multi_init): child 0 of chatmenu:options is the title and
 * children 1 to 5 are the options; key "n" picks child n.</li>
 * <li>The list ("menu" interface, scripts menu_createentry and menu_createentry_indexed): each entry is a text child
 * of menu:lj_layer1 labelled with its key, "1: Fishing Guild"; keys run 1-9 and then letters.</li>
 * </ul>
 */
public final class DialogKeys
{
	private DialogKeys()
	{
	}

	/**
	 * The chat dialog option {@code key} picks, from the dialog's children by child index (null where a child has no
	 * text), or null.
	 */
	public static String chatOption(String[] byIndex, char key)
	{
		if (byIndex == null || key < '1' || key > '5')
		{
			return null;
		}
		int n = key - '0';
		return n < byIndex.length ? byIndex[n] : null;
	}

	/** The list entry labelled with {@code key}, or null. */
	public static String listEntry(List<String> entries, char key)
	{
		if (entries == null)
		{
			return null;
		}
		String k = String.valueOf(Character.toUpperCase(key));
		for (String entry : entries)
		{
			if (k.equals(Text.listKey(entry)))
			{
				return entry;
			}
		}
		return null;
	}
}

package com.teleportpretile.data;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Fairy ring codes. The dials are set in the fairy ring interface and the code is sent with its Confirm button, so
 * the code is read from the dial varbits at that click, the way RuneLite's Fairy Ring plugin reads it.
 */
public final class FairyRings
{
	/** The letter each dial value shows (varbits FAIRYRING_1, FAIRYRING_2, FAIRYRING_3), as in RuneLite's plugin. */
	private static final String[] LEFT = {"A", "D", "C", "B"};
	private static final String[] MIDDLE = {"I", "L", "K", "J"};
	private static final String[] RIGHT = {"P", "S", "R", "Q"};
	private static final Pattern CODE = Pattern.compile("^[ABCD][IJKL][PQRS]$");
	/** "Last-destination (CKS)" on a fairy ring. */
	private static final Pattern LAST = Pattern.compile("\\(([A-Da-d][I-Li-l][P-Sp-s])\\)");

	/** The ring Zanaris is reached by ("Zanaris" on a fairy ring). */
	public static final String ZANARIS = "BKS";

	private FairyRings()
	{
	}

	/** The code the dials show, or null for a dial value out of range. */
	public static String code(int left, int middle, int right)
	{
		if (left < 0 || left > 3 || middle < 0 || middle > 3 || right < 0 || right > 3)
		{
			return null;
		}
		return LEFT[left] + MIDDLE[middle] + RIGHT[right];
	}

	public static boolean isCode(String s)
	{
		return s != null && CODE.matcher(s.toUpperCase()).matches();
	}

	/**
	 * The code a click on a fairy ring goes to without the dials: "Last-destination (CKS)", "Zanaris", or a code
	 * saved in its "Favourites" sub-menu ("CKS"); null for any other click (an empty favourite shows "Favourite 1").
	 */
	public static String codeOfOption(String option, String target)
	{
		String opt = Text.clean(option);
		if (Text.clean(target).isEmpty() && isCode(opt))
		{
			// a favourite picked from the ring's sub-menu, in case the ring's name can't be found for it
			return opt.toUpperCase();
		}
		if (!Text.key(target).equals("fairy ring"))
		{
			return null;
		}
		if (opt.equalsIgnoreCase("Zanaris"))
		{
			return ZANARIS;
		}
		if (isCode(opt))
		{
			return opt.toUpperCase();
		}
		Matcher m = LAST.matcher(opt);
		return opt.toLowerCase().startsWith("last-destination") && m.find() ? m.group(1).toUpperCase() : null;
	}
}

package com.teleportpretile.data;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The player's house as last seen: which room template sits in each 8x8 chunk of the instance, and the tile the
 * player arrived on. The house is an instance, so its tiles don't exist until the player is there; the Tile Markers
 * plugin saves a marker placed in it at the room template's tile, and draws it wherever that template is placed.
 * With the layout from the last visit the same can be done before arriving.
 *
 * <p>Scene coordinates throughout (tiles from the corner of the loaded scene); the chunk data is the client's
 * instance template chunks, decoded and rotated exactly as RuneLite's {@code WorldPoint.toLocalInstance} does.
 */
public final class HouseLayout
{
	/** Where the house portal, a teleport inside, a house tablet or a cape's "Home" puts the player. */
	public static final String PORTAL = "portal";
	/** Where the garden's spirit tree or fairy ring puts the player. */
	public static final String GARDEN = "garden";

	private static final int CHUNK = 8;

	/** The instance's template chunks, [plane][chunk x][chunk y], as the client gives them. */
	int[][][] chunks;
	/** Arrival tiles by entry ({@link #PORTAL}, {@link #GARDEN}): {scene x, scene y, plane}. */
	Map<String, int[]> entries = new HashMap<>();

	public HouseLayout()
	{
	}

	public HouseLayout(int[][][] chunks)
	{
		this.chunks = chunks;
	}

	/** Records where the player arrived for this entry. */
	public void arrived(String entry, int sceneX, int sceneY, int plane)
	{
		entries.put(entry, new int[]{sceneX, sceneY, plane});
	}

	/** The arrival tile {scene x, scene y, plane} for this entry, or null when never seen. */
	public int[] entry(String entry)
	{
		return entries == null ? null : entries.get(entry);
	}

	public boolean sameChunks(int[][][] other)
	{
		return java.util.Arrays.deepEquals(chunks, other);
	}

	/** One chunk of the house on a plane: where it is in the scene and which template it shows, how turned. */
	public static final class Placement
	{
		public final int sceneChunkX;
		public final int sceneChunkY;
		/** The template chunk's south-west world tile and plane. */
		public final int templateX;
		public final int templateY;
		public final int templatePlane;
		public final int rotation;

		Placement(int sceneChunkX, int sceneChunkY, int templateX, int templateY, int templatePlane, int rotation)
		{
			this.sceneChunkX = sceneChunkX;
			this.sceneChunkY = sceneChunkY;
			this.templateX = templateX;
			this.templateY = templateY;
			this.templatePlane = templatePlane;
			this.rotation = rotation;
		}

		/** True when the template world tile is in this chunk's template. */
		public boolean holds(int x, int y, int plane)
		{
			return plane == templatePlane && x >= templateX && x < templateX + CHUNK && y >= templateY && y < templateY + CHUNK;
		}

		/** The scene tile {x, y} where this chunk shows the template world tile (x, y). */
		public int[] toScene(int x, int y)
		{
			int px = sceneChunkX * CHUNK + (x & (CHUNK - 1));
			int py = sceneChunkY * CHUNK + (y & (CHUNK - 1));
			return rotate(px, py, rotation);
		}
	}

	/** The house's chunks on this plane that show a room template (empty chunks left out). */
	public List<Placement> placements(int plane)
	{
		List<Placement> out = new ArrayList<>();
		if (chunks == null || plane < 0 || plane >= chunks.length)
		{
			return out;
		}
		for (int x = 0; x < chunks[plane].length; x++)
		{
			for (int y = 0; y < chunks[plane][x].length; y++)
			{
				int data = chunks[plane][x][y];
				if (data <= 0)
				{
					continue;
				}
				int rotation = data >> 1 & 0x3;
				int templateY = (data >> 3 & 0x7FF) * CHUNK;
				int templateX = (data >> 14 & 0x3FF) * CHUNK;
				int templatePlane = data >> 24 & 0x3;
				out.add(new Placement(x, y, templateX, templateY, templatePlane, rotation));
			}
		}
		return out;
	}

	/** RuneLite's chunk rotation ({@code WorldPoint.rotate}): turns a tile within its 8x8 chunk. */
	static int[] rotate(int x, int y, int rotation)
	{
		int chunkX = x & ~(CHUNK - 1);
		int chunkY = y & ~(CHUNK - 1);
		int cx = x & (CHUNK - 1);
		int cy = y & (CHUNK - 1);
		switch (rotation)
		{
			case 1:
				return new int[]{chunkX + cy, chunkY + (CHUNK - 1 - cx)};
			case 2:
				return new int[]{chunkX + (CHUNK - 1 - cx), chunkY + (CHUNK - 1 - cy)};
			case 3:
				return new int[]{chunkX + (CHUNK - 1 - cy), chunkY + cx};
			default:
				return new int[]{x, y};
		}
	}

	/** Packs template chunk data the way the client does (for tests). */
	static int pack(int templateChunkX, int templateChunkY, int templatePlane, int rotation)
	{
		return templatePlane << 24 | templateChunkX << 14 | templateChunkY << 3 | rotation << 1;
	}
}

package com.teleportpretile.data;

import net.runelite.api.gameval.VarbitID;

/**
 * Items with a "last destination" option. The game keeps the last place in a varbit, but the varbit is set by the
 * server and nothing in the client says which value means which place. So the plugin learns it from play: each time
 * the player lands from one of the item's ordinary teleports, the varbit's value then is that teleport's destination.
 * The quetzal's value also changes when the player rides the quetzal network; a value learned once keeps working.
 */
public enum LastDestination
{
	/** quetzal_last_destination; "Last-destination" on every quetzal whistle. */
	QUETZAL_WHISTLE(VarbitID.QUETZAL_LAST_DESTINATION, "Last-destination", "quetzal whistle"),
	/** ring_of_elements_last_destination; "Last Destination" in the inventory and when worn. */
	RING_OF_THE_ELEMENTS(VarbitID.RING_OF_ELEMENTS_LAST_DESTINATION, "Last Destination", "ring of the elements"),
	/** pharaohs_sceptre_last_teleport; "Last-Teleport". */
	PHARAOHS_SCEPTRE(VarbitID.PHARAOHS_SCEPTRE_LAST_TELEPORT, "Last-Teleport", "pharaoh's sceptre");

	private final int varbit;
	private final String option;
	/** Part of the item's name, in lower case; the item's teleports name it in their menu target. */
	private final String item;

	LastDestination(int varbit, String option, String item)
	{
		this.varbit = varbit;
		this.option = option;
		this.item = item;
	}

	public int getVarbit()
	{
		return varbit;
	}

	/** The item whose "last destination" option this click is, or null. */
	public static LastDestination clicked(String option, String target)
	{
		String opt = Text.key(option);
		String tgt = Text.key(target);
		for (LastDestination d : values())
		{
			if (d.option.equalsIgnoreCase(opt) && tgt.contains(d.item))
			{
				return d;
			}
		}
		return null;
	}

	/** The item this teleport belongs to, or null when it isn't one of these items' teleports. */
	public static LastDestination of(Teleport t)
	{
		String tgt = Text.key(t.getMenu().getTarget());
		for (LastDestination d : values())
		{
			if (tgt.contains(d.item))
			{
				return d;
			}
		}
		return null;
	}

	/** The config key holding the teleport id for one varbit value. */
	public String key(int value)
	{
		return name() + "." + value;
	}
}

package com.teleportpretile.data;

import lombok.Value;

/**
 * What the player clicks to start a teleport, as Best Path's data writes it:
 * <ul>
 * <li>{@code v|Cast|Varrock Teleport}: the menu option and target.</li>
 * <li>{@code n|Edgeville|Amulet of glory}: the same, where the option names the destination.</li>
 * <li>{@code c|Rub|Amulet of glory|Edgeville}: the click opens a dialog, list or sub-menu, then the choice is picked.
 * Worn items often show the choice straight away as a menu option ("Edgeville Amulet of glory").</li>
 * </ul>
 */
@Value
public class MenuSpec
{
	public enum Style
	{
		VERB, NAMED, CHOICE
	}

	Style style;
	String option;
	String target;
	/** {@link Style#CHOICE} only, else null. */
	String choice;
	/**
	 * {@link Style#CHOICE} only: the keyboard key that picks the choice where the game's list fixes it ("5" in the
	 * house jewellery box, "A" for a spirit tree), else null.
	 */
	String key;

	public static MenuSpec parse(String s)
	{
		String[] p = s.split("\\|", -1);
		if (p.length < 3)
		{
			throw new IllegalArgumentException("menu text needs at least 3 parts: " + s);
		}
		switch (p[0])
		{
			case "v":
				return new MenuSpec(Style.VERB, p[1], p[2], null, null);
			case "n":
				return new MenuSpec(Style.NAMED, p[1], p[2], null, null);
			case "c":
				// "c|||BLQ": a stop known only by its choice (reached by the fairy ring dials, not a click)
				if (p.length < 4 || p[3].isEmpty())
				{
					throw new IllegalArgumentException("choice menu text has no choice: " + s);
				}
				String key = p.length > 4 && !p[4].isEmpty() ? p[4] : null;
				return new MenuSpec(Style.CHOICE, p[1], p[2], p[3], key);
			default:
				throw new IllegalArgumentException("unknown menu text style: " + s);
		}
	}
}

package com.teleportpretile.data;

import java.util.List;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import lombok.Value;

/** One teleport from the bundled data: how it is started and where it lands. Immutable. */
@Value
public class Teleport
{
	public enum Kind
	{
		/** Used from anywhere: spells, items. */
		TELEPORT,
		/** A stop of a network (fairy rings, spirit trees, ...), reached from any other stop. */
		NETWORK,
		/** Boarded at one place ({@link #hasFrom()}): levers, portals, boats, charter ships, the house's rides. */
		RIDE
	}

	String id;
	String name;
	String category;
	int x;
	int y;
	int plane;
	/** Roughly how long the teleport takes, in game ticks. */
	int ticks;
	/**
	 * True when the data says the teleport lands on a random tile around the destination (the destination is then
	 * the middle of that area); false lands exactly on the destination.
	 */
	boolean randomLanding;
	/**
	 * How many whole tiles from the destination the landing can be: 0 for an exact landing, -1 for a zone whose size
	 * the data doesn't know yet.
	 */
	int maxOffset;
	MenuSpec menu;
	/** Item ids that can start it (empty when the data names the item only by its name). */
	Set<Integer> itemIds;
	List<Condition> conditions;
	Kind kind;
	/** Where a ride is boarded; {@link #hasFrom()} is false when it can be started anywhere. */
	int fromX;
	int fromY;
	int fromPlane;
	/**
	 * Where in the player's house this lands ({@link HouseLayout#PORTAL} or {@link HouseLayout#GARDEN}), or null for a
	 * fixed destination. The house is an instance: its tiles are only known from the player's last visit.
	 */
	String houseEntry;

	public boolean isHouse()
	{
		return houseEntry != null;
	}

	public boolean hasFrom()
	{
		return fromX > 0;
	}

	/**
	 * True when the data says the landing can be {@code tiles} or more tiles from the destination. A zone of unknown
	 * size isn't, until the data knows its size.
	 */
	public boolean couldBeOffBy(int tiles)
	{
		return randomLanding && maxOffset >= 0 && maxOffset >= tiles;
	}

	public boolean conditionsMet(IntUnaryOperator varbits)
	{
		for (Condition c : conditions)
		{
			if (!c.test(varbits))
			{
				return false;
			}
		}
		return true;
	}
}

package com.teleportpretile.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import java.util.function.Predicate;

/** The bundled teleports and the lookups that turn a click into a teleport. Immutable. */
public final class TeleportCatalog
{
	/** Teleports that share a click count as one place when they land this close together (in tiles). */
	static final int SAME_PLACE_TILES = 8;
	/** A ride is only taken for a click this close (in tiles) to where it is boarded. */
	static final int BOARDING_TILES = 20;

	private final List<Teleport> teleports;

	private TeleportCatalog(List<Teleport> teleports)
	{
		this.teleports = Collections.unmodifiableList(teleports);
	}

	public static TeleportCatalog load(InputStream in) throws IOException
	{
		return parse(new InputStreamReader(in, StandardCharsets.UTF_8));
	}

	/** Reads teleports.tsv: "#" comment lines, then one tab-separated teleport per line. Bad lines throw, naming the line. */
	public static TeleportCatalog parse(Reader reader) throws IOException
	{
		List<Teleport> list = new ArrayList<>();
		BufferedReader r = new BufferedReader(reader);
		String line;
		int n = 0;
		while ((line = r.readLine()) != null)
		{
			n++;
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			try
			{
				list.add(parseLine(line));
			}
			catch (RuntimeException e)
			{
				throw new IOException("teleports.tsv line " + n + ": " + e.getMessage(), e);
			}
		}
		return new TeleportCatalog(list);
	}

	private static Teleport parseLine(String line)
	{
		String[] c = line.split("\t", -1);
		if (c.length < 11)
		{
			throw new IllegalArgumentException("expected 11 columns, got " + c.length);
		}
		String houseEntry = c[3].startsWith("house:") ? c[3].substring("house:".length()) : null;
		String[] dest = houseEntry != null ? new String[]{"0", "0", "0"} : c[3].split(",");
		Set<Integer> ids = new LinkedHashSet<>();
		for (String id : c[7].split(","))
		{
			if (!id.isEmpty())
			{
				ids.add(Integer.parseInt(id.trim()));
			}
		}
		List<Condition> conditions = new ArrayList<>();
		for (String cond : c[8].split(";"))
		{
			Condition parsed = cond.isEmpty() ? null : Condition.parse(cond);
			if (parsed != null)
			{
				conditions.add(parsed);
			}
		}
		int[] from = {0, 0, 0};
		if (!c[10].trim().isEmpty())
		{
			String[] f = c[10].split(",");
			for (int i = 0; i < 3; i++)
			{
				from[i] = Integer.parseInt(f[i].trim());
			}
		}
		return new Teleport(c[0], c[1], c[2], Integer.parseInt(dest[0].trim()), Integer.parseInt(dest[1].trim()),
			Integer.parseInt(dest[2].trim()), Integer.parseInt(c[4]), !c[5].trim().isEmpty(), zoneOffset(c[5]), MenuSpec.parse(c[6]),
			Collections.unmodifiableSet(ids), Collections.unmodifiableList(conditions),
			Teleport.Kind.valueOf(c[9].trim().toUpperCase()), from[0], from[1], from[2], houseEntry);
	}

	/** The zone column: empty for an exact landing (0), "?" for a zone of unknown size (-1), else whole tiles. */
	private static int zoneOffset(String s)
	{
		String t = s.trim();
		if (t.isEmpty())
		{
			return 0;
		}
		if (t.equals("?"))
		{
			return -1;
		}
		int n = Integer.parseInt(t);
		if (n < 1)
		{
			throw new IllegalArgumentException("zone must be empty, ? or at least 1, got '" + s + "'");
		}
		return n;
	}

	public List<Teleport> all()
	{
		return teleports;
	}

	/** The teleport with this id, or null. */
	public Teleport byId(String id)
	{
		for (Teleport t : teleports)
		{
			if (t.getId().equals(id))
			{
				return t;
			}
		}
		return null;
	}

	/**
	 * Teleports this click starts straight away: a verb or named click, or a worn item's option that is the
	 * choice itself ("Edgeville" on a worn Amulet of glory).
	 */
	public List<Teleport> started(String option, String target, int itemId)
	{
		String opt = Text.key(option);
		return best(target, itemId, t ->
		{
			MenuSpec m = t.getMenu();
			String wanted = m.getStyle() == MenuSpec.Style.CHOICE ? m.getChoice() : m.getOption();
			return Text.key(wanted).equals(opt);
		});
	}

	/**
	 * Teleports whose dialog or list this click opens ("Rub" on an Amulet of glory); one is picked next. A click on
	 * any stop of a network opens the whole network: the game names some stops differently ("Spirit tree" and
	 * "Spirit Tree").
	 */
	public List<Teleport> opened(String option, String target, int itemId)
	{
		String opt = Text.key(option);
		List<Teleport> found = best(target, itemId, t -> t.getMenu().getStyle() == MenuSpec.Style.CHOICE
			&& Text.key(t.getMenu().getOption()).equals(opt));
		Set<String> networks = new LinkedHashSet<>();
		for (Teleport t : found)
		{
			if (t.getKind() == Teleport.Kind.NETWORK)
			{
				networks.add(t.getCategory());
			}
		}
		if (networks.isEmpty())
		{
			return found;
		}
		List<Teleport> out = new ArrayList<>(found);
		for (Teleport t : teleports)
		{
			if (t.getKind() == Teleport.Kind.NETWORK && networks.contains(t.getCategory()) && !out.contains(t))
			{
				out.add(t);
			}
		}
		return out;
	}

	/** Of the teleports a click {@link #opened(String, String, int)}, those this dialog or list entry picks. */
	public static List<Teleport> chosen(List<Teleport> opened, String entry)
	{
		List<Teleport> out = new ArrayList<>();
		for (Teleport t : opened)
		{
			if (Text.sameChoice(entry, t.getMenu().getChoice()))
			{
				out.add(t);
			}
		}
		return out;
	}

	/**
	 * Teleports with the right option whose target matches the click, keeping only the closest kind of match:
	 * the clicked item's id, then the exact name, the name in any letter case, the name with a word in front (the
	 * house's "Ornate Jewellery Box" for the data's "Jewellery Box"), and last the name without its tier number
	 * ("Desert amulet 3" for the data's "Desert amulet 2").
	 */
	private List<Teleport> best(String target, int itemId, Predicate<Teleport> optionMatches)
	{
		List<List<Teleport>> tiers = new ArrayList<>();
		for (int i = 0; i < 5; i++)
		{
			tiers.add(new ArrayList<>());
		}
		String base = Text.baseName(target);
		for (Teleport t : teleports)
		{
			if (!optionMatches.test(t))
			{
				continue;
			}
			String expected = t.getMenu().getTarget();
			if (itemId > 0 && t.getItemIds().contains(itemId))
			{
				tiers.get(0).add(t);
			}
			else if (Text.sameName(target, expected) && Text.clean(target).startsWith(Text.clean(expected)))
			{
				tiers.get(1).add(t);
			}
			else if (Text.sameName(target, expected))
			{
				tiers.get(2).add(t);
			}
			else if (!Text.key(expected).isEmpty() && Text.key(target).endsWith(" " + Text.key(expected)))
			{
				tiers.get(3).add(t);
			}
			else if (!base.isEmpty() && base.equals(Text.baseName(expected)))
			{
				tiers.get(4).add(t);
			}
		}
		for (List<Teleport> tier : tiers)
		{
			if (!tier.isEmpty())
			{
				return tier;
			}
		}
		return Collections.emptyList();
	}

	/**
	 * These candidates with the rides boarded somewhere else left out: a ride counts only when the click is within
	 * {@link #BOARDING_TILES} of where it is boarded, and only the nearest boarding place counts. Teleports and network
	 * stops, which have no boarding place, are kept.
	 */
	public static List<Teleport> near(List<Teleport> candidates, int x, int y, int plane)
	{
		int best = Integer.MAX_VALUE;
		for (Teleport t : candidates)
		{
			if (t.hasFrom() && t.getFromPlane() == plane)
			{
				best = Math.min(best, Math.max(Math.abs(t.getFromX() - x), Math.abs(t.getFromY() - y)));
			}
		}
		List<Teleport> out = new ArrayList<>();
		for (Teleport t : candidates)
		{
			if (!t.hasFrom())
			{
				out.add(t);
			}
			else if (best <= BOARDING_TILES && t.getFromPlane() == plane
				&& Math.max(Math.abs(t.getFromX() - x), Math.abs(t.getFromY() - y)) == best)
			{
				out.add(t);
			}
		}
		return out;
	}

	/** Of the teleports a click opened, those whose choice the game's list puts on this key (the data's fixed keys). */
	public static List<Teleport> chosenByKey(List<Teleport> opened, char key)
	{
		List<Teleport> out = new ArrayList<>();
		for (Teleport t : opened)
		{
			String k = t.getMenu().getKey();
			if (k != null && k.length() == 1 && Character.toUpperCase(k.charAt(0)) == Character.toUpperCase(key))
			{
				out.add(t);
			}
		}
		return out;
	}

	/** The fairy ring stops with this code ("CKS"). */
	public List<Teleport> fairyRing(String code)
	{
		List<Teleport> out = new ArrayList<>();
		for (Teleport t : teleports)
		{
			MenuSpec m = t.getMenu();
			if (t.getKind() == Teleport.Kind.NETWORK && m.getStyle() == MenuSpec.Style.CHOICE
				&& m.getChoice().equalsIgnoreCase(code) && FairyRings.isCode(m.getChoice()))
			{
				out.add(t);
			}
		}
		return out;
	}

	/**
	 * The one teleport of these the player is using: those whose varbit conditions hold, as long as they all land
	 * in about the same place. Null when none fits or they go to different places (the plugin then shows nothing
	 * rather than guess).
	 */
	public static Teleport resolve(List<Teleport> candidates, IntUnaryOperator varbits)
	{
		Teleport first = null;
		for (Teleport t : candidates)
		{
			if (!t.conditionsMet(varbits))
			{
				continue;
			}
			if (first == null)
			{
				first = t;
			}
			else if (t.getPlane() != first.getPlane()
				|| Math.max(Math.abs(t.getX() - first.getX()), Math.abs(t.getY() - first.getY())) > SAME_PLACE_TILES)
			{
				return null;
			}
		}
		return first;
	}
}

package com.teleportpretile.data;

import lombok.Getter;

/**
 * Follows one teleport or ride from the click to the arrival, tick by tick. The plugin feeds it the player's tile and
 * animation each game tick; it says when the player has arrived, or when the trip didn't happen after all.
 *
 * <p>The player has arrived when they move more than {@link #JUMP_TILES} in one tick or change plane: walking and
 * running move at most 2 tiles a tick.
 * <ul>
 * <li>A teleport ({@link Teleport.Kind#TELEPORT}) must start (an animation or graphic) within {@link #START_TICKS};
 * walking off afterwards cancels it.</li>
 * <li>A ride or network trip may first walk to where it is boarded, so movement doesn't cancel it; it gives up after
 * its travel time plus {@link #WALK_TICKS}.</li>
 * </ul>
 */
public final class TeleportTracker
{
	/** Ticks after the click for a teleport's animation to start before giving up (failed or refused). */
	static final int START_TICKS = 3;
	/** Extra ticks past the data's travel time before giving up on the arrival. */
	static final int ARRIVAL_SLACK_TICKS = 6;
	/** Ticks a ride may spend walking to where it is boarded. */
	static final int WALK_TICKS = 30;
	/** A move of more tiles than this in one tick is the landing; walking and running move at most 2. */
	static final int JUMP_TILES = 3;

	public enum Result
	{
		/** Still on the way. */
		WAITING,
		/** The player has landed: see {@link #getArrivalX()}. */
		ARRIVED,
		/** The trip didn't happen, was interrupted or took far too long. */
		CANCELLED
	}

	@Getter
	private final Teleport teleport;
	private final int startTick;
	private final int baselineAnimation;
	private int lastX;
	private int lastY;
	private int lastPlane;
	@Getter
	private boolean started;
	@Getter
	private int arrivalX;
	@Getter
	private int arrivalY;
	@Getter
	private int arrivalPlane;

	/**
	 * @param animation the player's animation at the click, so an animation already playing (skilling, say) isn't
	 *                  taken for a teleport starting
	 */
	public TeleportTracker(Teleport teleport, int tick, int x, int y, int plane, int animation)
	{
		this.teleport = teleport;
		this.startTick = tick;
		this.baselineAnimation = animation;
		this.lastX = x;
		this.lastY = y;
		this.lastPlane = plane;
		// a ride or network trip has nothing to wait for: it is shown from the click
		this.started = teleport.getKind() != Teleport.Kind.TELEPORT;
	}

	/**
	 * One game tick.
	 *
	 * @param animation the player's animation (-1 for none)
	 * @param spotAnimChanged true when a graphic started on the player since the click
	 */
	public Result tick(int tick, int x, int y, int plane, int animation, boolean spotAnimChanged)
	{
		int moved = Math.max(Math.abs(x - lastX), Math.abs(y - lastY));
		boolean planeChanged = plane != lastPlane;
		lastX = x;
		lastY = y;
		lastPlane = plane;
		if (planeChanged || moved > JUMP_TILES)
		{
			arrivalX = x;
			arrivalY = y;
			arrivalPlane = plane;
			return Result.ARRIVED;
		}
		int elapsed = tick - startTick;
		if (teleport.getKind() != Teleport.Kind.TELEPORT)
		{
			return elapsed > Math.max(teleport.getTicks(), 1) + WALK_TICKS + ARRIVAL_SLACK_TICKS
				? Result.CANCELLED : Result.WAITING;
		}
		if (!started)
		{
			if ((animation != -1 && animation != baselineAnimation) || spotAnimChanged)
			{
				started = true;
			}
			else if (elapsed > START_TICKS)
			{
				return Result.CANCELLED;
			}
			// still running to a stop after the click
			return Result.WAITING;
		}
		if (moved > 0)
		{
			// walked off mid-cast (a home teleport can be interrupted)
			return Result.CANCELLED;
		}
		if (elapsed > Math.max(teleport.getTicks(), 1) + ARRIVAL_SLACK_TICKS)
		{
			return Result.CANCELLED;
		}
		return Result.WAITING;
	}
}

package com.teleportpretile.data;

import java.util.Locale;
import java.util.regex.Pattern;

/** Cleans menu and widget text so it can be compared with the teleport data. */
public final class Text
{
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	/**
	 * "1: Edgeville" (the game's lists label entries 1-9 and then letters: "A: Edgeville"), and also "1. Edgeville" or
	 * "[1] Edgeville".
	 */
	private static final Pattern NUMBERING = Pattern.compile("^\\[?([0-9]+|[A-Z])[\\].:)]\\s+");
	/** "(4)", "(t4)", "(i)", "(uncharged)" after an item name. */
	private static final Pattern SUFFIX = Pattern.compile("\\s*\\([^)]*\\)\\s*$");
	/** A tier number at the end of an item name: "Desert amulet 3". */
	private static final Pattern TIER = Pattern.compile("\\s+\\d+$");

	private Text()
	{
	}

	/** Removes colour and image tags, swaps non-breaking spaces for spaces and trims. Never null. */
	public static String clean(String s)
	{
		if (s == null)
		{
			return "";
		}
		return TAGS.matcher(s).replaceAll("").replace(' ', ' ').trim();
	}

	/** {@link #clean(String)} and then lower case, for comparing. */
	public static String key(String s)
	{
		return clean(s).toLowerCase(Locale.ROOT);
	}

	/** The key label a list entry starts with ("1: Fishing Guild" gives "1", "A: Kourend" gives "A"), or null. */
	public static String listKey(String s)
	{
		java.util.regex.Matcher m = NUMBERING.matcher(clean(s));
		return m.find() ? m.group(1) : null;
	}

	/** The entry without its leading number: "1: Fishing Guild" gives "Fishing Guild". */
	public static String withoutNumbering(String s)
	{
		return NUMBERING.matcher(clean(s)).replaceFirst("");
	}

	/**
	 * True when the clicked item or spell name {@code actual} is the data's name {@code expected}, maybe with charges
	 * or a variant after it: "Amulet of glory(4)" and "Amulet of glory (t4)" are both "Amulet of glory".
	 */
	public static boolean sameName(String actual, String expected)
	{
		String a = key(actual);
		String e = key(expected);
		if (a.equals(e))
		{
			return true;
		}
		if (!a.startsWith(e))
		{
			return false;
		}
		String rest = a.substring(e.length());
		return rest.startsWith("(") || rest.startsWith(" (");
	}

	/** The name with no charges and no tier number: "Desert amulet 3" and "Desert amulet 2" are both "desert amulet". */
	public static String baseName(String s)
	{
		String k = key(s);
		String prev;
		do
		{
			prev = k;
			k = SUFFIX.matcher(k).replaceFirst("");
			k = TIER.matcher(k).replaceFirst("");
		}
		while (!k.equals(prev));
		return k;
	}

	/**
	 * True when a dialog or list entry is the data's choice text ("Edgeville", "2. Edgeville"), or says it as a whole
	 * phrase ("Travel to Bedabin Camp").
	 */
	public static boolean sameChoice(String entry, String choice)
	{
		String a = key(withoutNumbering(entry));
		String c = key(choice);
		if (a.isEmpty() || c.isEmpty())
		{
			return false;
		}
		if (a.equals(c))
		{
			return true;
		}
		// "Edgeville." or "Edgeville (Wilderness level 1)": the choice then something that isn't a letter or digit
		if (a.startsWith(c) && !Character.isLetterOrDigit(a.charAt(c.length())))
		{
			return true;
		}
		// "Travel to Bedabin Camp": the choice as a whole phrase inside the entry
		for (int i = a.indexOf(c); i >= 0; i = a.indexOf(c, i + 1))
		{
			boolean startOk = i == 0 || !Character.isLetterOrDigit(a.charAt(i - 1));
			int end = i + c.length();
			boolean endOk = end == a.length() || !Character.isLetterOrDigit(a.charAt(end));
			if (startOk && endOk)
			{
				return true;
			}
		}
		return false;
	}
}

package com.teleportpretile.data;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * The ground's height at the marked tiles around one landing spot, learned the first time the player lands there,
 * so later trips can draw each marker at its real height instead of flat at the player's feet.
 *
 * <p>Heights are kept relative to the landing tile's middle (in the game's height units, 128 to a tile, where more
 * negative is higher) for each tile's four corners, in the order (-x,-y), (+x,-y), (+x,+y), (-x,+y). Tiles level
 * with the landing spot aren't stored, so flat places cost almost nothing to save.
 */
public final class TileHeights
{
	/** The ground height at a scene corner, or null where it isn't loaded. */
	public interface Ground
	{
		/**
		 * @param x world tile x
		 * @param y world tile y
		 * @param corner 0-3, in the class's corner order
		 */
		Integer corner(int x, int y, int corner);
	}

	private static final int[] FLAT = {0, 0, 0, 0};

	private final Map<Long, int[]> tiles;

	private TileHeights(Map<Long, int[]> tiles)
	{
		this.tiles = tiles;
	}

	/**
	 * Reads the heights of these marked tiles (x, y pairs) around the landing tile (cx, cy) from the loaded ground.
	 * Null when the landing tile itself isn't loaded. Tiles that aren't loaded are left out (drawn flat).
	 */
	public static TileHeights learn(int cx, int cy, int[][] marked, Ground ground)
	{
		int sum = 0;
		for (int c = 0; c < 4; c++)
		{
			Integer h = ground.corner(cx, cy, c);
			if (h == null)
			{
				return null;
			}
			sum += h;
		}
		// the middle of a tile is the mean of its corners (the game blends a tile's corners)
		int middle = Math.round(sum / 4f);
		Map<Long, int[]> out = new HashMap<>();
		for (int[] xy : marked)
		{
			int[] rel = new int[4];
			boolean level = true;
			boolean loaded = true;
			for (int c = 0; c < 4 && loaded; c++)
			{
				Integer h = ground.corner(xy[0], xy[1], c);
				if (h == null)
				{
					loaded = false;
					break;
				}
				rel[c] = h - middle;
				level &= rel[c] == 0;
			}
			if (loaded && !level)
			{
				out.put(key(xy[0] - cx, xy[1] - cy), rel);
			}
		}
		return new TileHeights(out);
	}

	/** The corners' heights of the tile (dx, dy) tiles from the landing tile, relative to it. Never null. */
	public int[] at(int dx, int dy)
	{
		int[] h = tiles.get(key(dx, dy));
		return h != null ? h : FLAT;
	}

	/**
	 * True when this knows a height that {@code before} didn't (a tile it didn't have, or a different height), so the
	 * trip taught something new. {@code before} null: nothing was known.
	 */
	public boolean addsTo(TileHeights before)
	{
		for (Map.Entry<Long, int[]> e : tiles.entrySet())
		{
			int[] old = before == null ? null : before.tiles.get(e.getKey());
			if (old == null || !Arrays.equals(old, e.getValue()))
			{
				return true;
			}
		}
		return false;
	}

	public int size()
	{
		return tiles.size();
	}

	/** Saved form: "dx,dy:h0,h1,h2,h3" per sloped or raised tile, joined by ";"; empty when all are level. */
	public String encode()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Long, int[]> e : tiles.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			int[] h = e.getValue();
			sb.append(dx(e.getKey())).append(',').append(dy(e.getKey())).append(':')
				.append(h[0]).append(',').append(h[1]).append(',').append(h[2]).append(',').append(h[3]);
		}
		return sb.toString();
	}

	/** Reads {@link #encode()}'s form; null for text it can't read (then nothing was learned). */
	public static TileHeights decode(String s)
	{
		if (s == null)
		{
			return null;
		}
		if (s.isEmpty())
		{
			return new TileHeights(Collections.emptyMap());
		}
		Map<Long, int[]> out = new HashMap<>();
		try
		{
			for (String part : s.split(";"))
			{
				String[] kv = part.split(":");
				String[] d = kv[0].split(",");
				String[] h = kv[1].split(",");
				if (d.length != 2 || h.length != 4)
				{
					return null;
				}
				out.put(key(Integer.parseInt(d[0].trim()), Integer.parseInt(d[1].trim())), new int[]{
					Integer.parseInt(h[0].trim()), Integer.parseInt(h[1].trim()), Integer.parseInt(h[2].trim()),
					Integer.parseInt(h[3].trim())});
			}
		}
		catch (RuntimeException e)
		{
			return null;
		}
		return new TileHeights(out);
	}

	private static long key(int dx, int dy)
	{
		return ((long) dx << 32) | (dy & 0xffffffffL);
	}

	private static int dx(long key)
	{
		return (int) (key >> 32);
	}

	private static int dy(long key)
	{
		return (int) key;
	}
}

package com.teleportpretile.render;

/**
 * Timing of the blink that shows the player the plugin just learned something on this trip (the house's layout, what
 * a "last destination" means): {@link #TIMES} flashes, each {@link #ON_MILLIS} shown then {@link #OFF_MILLIS} hidden.
 */
public final class Blink
{
	public static final int TIMES = 3;
	public static final long ON_MILLIS = 700;
	public static final long OFF_MILLIS = 500;

	private final long startMillis;

	public Blink(long startMillis)
	{
		this.startMillis = startMillis;
	}

	/** True while a flash is showing at this time. */
	public boolean visible(long nowMillis)
	{
		long t = nowMillis - startMillis;
		if (t < 0 || isOver(nowMillis))
		{
			return false;
		}
		return t % (ON_MILLIS + OFF_MILLIS) < ON_MILLIS;
	}

	public boolean isOver(long nowMillis)
	{
		return nowMillis - startMillis >= TIMES * (ON_MILLIS + OFF_MILLIS);
	}
}

package com.teleportpretile.render;

/** When a colour override applies to a marker, by how opaque the marker's own outline is. */
public enum OverrideWhen
{
	/** Every marker, whatever its opacity: the threshold number is ignored. */
	ANY("Any"),
	ABOVE("Above"),
	BELOW("Below"),
	EXACTLY("Exactly");

	private final String name;

	OverrideWhen(String name)
	{
		this.name = name;
	}

	/**
	 * True when an outline's alpha is above, below or exactly the threshold (always, for {@link #ANY}); both are
	 * 0-255, as in the colour pickers.
	 */
	public boolean matches(int alpha, int threshold)
	{
		switch (this)
		{
			case ANY:
				return true;
			case ABOVE:
				return alpha > threshold;
			case BELOW:
				return alpha < threshold;
			case EXACTLY:
			default:
				return alpha == threshold;
		}
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.teleportpretile.render;

/**
 * Projects a point in the game's local 3D coordinates to the canvas, with the same maths as RuneLite's
 * {@code Perspective.localToCanvas} but with no scene bounds check: the ghost markers sit where the destination's
 * tiles will be once the player has landed, which can be outside the scene that is loaded now.
 */
public final class Projector
{
	private final double camX;
	private final double camY;
	private final double camZ;
	private final double pitchSin;
	private final double pitchCos;
	private final double yawSin;
	private final double yawCos;
	private final int scale;
	private final int viewportWidth;
	private final int viewportHeight;
	private final int viewportX;
	private final int viewportY;

	/**
	 * @param pitch camera pitch in radians
	 * @param yaw   camera yaw in radians
	 */
	public Projector(double camX, double camY, double camZ, double pitch, double yaw, int scale,
		int viewportWidth, int viewportHeight, int viewportX, int viewportY)
	{
		this.camX = camX;
		this.camY = camY;
		this.camZ = camZ;
		this.pitchSin = Math.sin(pitch);
		this.pitchCos = Math.cos(pitch);
		this.yawSin = Math.sin(yaw);
		this.yawCos = Math.cos(yaw);
		this.scale = scale;
		this.viewportWidth = viewportWidth;
		this.viewportHeight = viewportHeight;
		this.viewportX = viewportX;
		this.viewportY = viewportY;
	}

	/** Canvas {x, y} of local point (x, y) at height z, or null when it is behind or too close to the camera. */
	public double[] project(double x, double y, double z)
	{
		double fx = x - camX;
		double fy = y - camY;
		double fz = z - camZ;
		double x1 = fx * yawCos + fy * yawSin;
		double y1 = fy * yawCos - fx * yawSin;
		double y2 = fz * pitchCos - y1 * pitchSin;
		double z1 = y1 * pitchCos + fz * pitchSin;
		if (z1 < 50)
		{
			return null;
		}
		return new double[]{
			viewportWidth / 2.0 + x1 * scale / z1 + viewportX,
			viewportHeight / 2.0 + y2 * scale / z1 + viewportY
		};
	}
}

package com.teleportpretile;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BlurLayersTest
{
	/** How opaque the piled-up layers are in band k (1 = next to the outline): layers k..n all cover it. */
	private static double covered(double[] a, int k)
	{
		double clear = 1;
		for (int j = k; j <= a.length; j++)
		{
			clear *= 1 - a[j - 1];
		}
		return 1 - clear;
	}

	@Test
	public void strongestNextToTheOutlineAndFadingOut()
	{
		for (double reach : new double[]{2, 9, 18, 40, 200})
		{
			double[] a = TeleportPreTileOverlay.blurLayerAlphas(reach);
			assertTrue(a.length >= 1 && a.length <= 12);
			double prev = 1;
			for (int k = 1; k <= a.length; k++)
			{
				assertTrue(a[k - 1] >= 0 && a[k - 1] <= 1);
				double c = covered(a, k);
				assertTrue("fades with distance at reach " + reach, c <= prev + 1e-9);
				prev = c;
			}
			assertEquals("the peak next to the outline", 0.6, covered(a, 1), 1e-9);
			assertTrue("all but gone at the edge", covered(a, a.length) < 0.25 || a.length == 1);
		}
	}

	@Test
	public void followsABellCurve()
	{
		double[] a = TeleportPreTileOverlay.blurLayerAlphas(18);
		int n = a.length;
		double sigma = 1 / 3.0;
		for (int k = 1; k <= n; k++)
		{
			double d = (k - 1) / (double) n;
			assertEquals(0.6 * Math.exp(-0.5 * d * d / (sigma * sigma)), covered(a, k), 1e-9);
		}
	}
}

